/* Generated from 10 DSKP-reviewed packs for 11 classes. */
const CONTENT_PACKS={"y1-medium":{"year":1,"levelLabel":"Explorer adventure","missions":[{"id":"y1-market","title":"Hello Village","topic":"Meet your friends · names and age","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"subtitle":"Meet the villagers","guide":"Tap a word block. Say hello to a new friend!","taskLabel":"Friend greeted","reminder":"Use the words in the story. Tap Listen to hear them.","tasks":[{"prompt":"Hello! My name ___ Hana.","options":["am","is","are"],"answer":"is","full":"Hello! My name is Hana.","hint":"Say: My name is Hana.","explain":"My name is Hana. We use is after My name.","scene":"girl"},{"prompt":"I ___ seven.","options":["is","are","am"],"answer":"am","full":"I am seven.","hint":"Say: I am seven.","explain":"I am seven. Am goes with I.","scene":"boy"},{"prompt":"A boy is called Dan. ___ name is Dan.","options":["Her","His"],"answer":"His","full":"His name is Dan.","hint":"Dan is a boy. Say: His name is Dan.","explain":"His tells us the name of the boy.","scene":"boy"},{"prompt":"A girl is called May. ___ name is May.","options":["Her","His"],"answer":"Her","full":"Her name is May.","hint":"May is a girl. Say: Her name is May.","explain":"Her tells us the name of the girl.","scene":"girl"},{"prompt":"Ben is six. How ___ is Ben?","options":["name","old"],"answer":"old","full":"How old is Ben?","hint":"Ask How old? to find out an age.","explain":"How old is Ben? The answer is six.","scene":"boy"}]},{"id":"y1-bridge","title":"Toy Bridge","topic":"My toys · his and her","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"subtitle":"Help friends find their toys","guide":"Tap a word block to add a bridge block. Return each toy to its owner!","taskLabel":"Bridge block added","reminder":"His tells us about a boy. Her tells us about a girl.","tasks":[{"prompt":"This ball belongs to Dan. It is ___ ball.","options":["his","her"],"answer":"his","full":"It is his ball.","hint":"Dan is a boy. His ball belongs to Dan.","explain":"His ball is the ball that belongs to Dan.","scene":"ball"},{"prompt":"This doll belongs to May. It is ___ doll.","options":["his","her"],"answer":"her","full":"It is her doll.","hint":"May is a girl. Her doll belongs to May.","explain":"Her doll is the doll that belongs to May.","scene":"girl"},{"prompt":"Ben is a boy. ___ is six.","options":["He","She"],"answer":"He","full":"He is six.","hint":"Ben is a boy. Use He.","explain":"He takes the place of Ben.","scene":"boy"},{"prompt":"Hana is a girl. ___ is seven.","options":["He","She"],"answer":"She","full":"She is seven.","hint":"Hana is a girl. Use She.","explain":"She takes the place of Hana.","scene":"girl"},{"prompt":"May has a kite. ___ favourite toy is her kite.","options":["His","Her"],"answer":"Her","full":"Her favourite toy is her kite.","hint":"The kite belongs to May. Use Her.","explain":"Her favourite toy is her kite. We are talking about May.","scene":"girl"}]},{"id":"y1-train","title":"Toy Train","topic":"Toy labels · a and an","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"subtitle":"Give the toys a label","guide":"Tap the word carriages in order. Build a toy label to move the train!","taskLabel":"Toy delivered","reminder":"Use a before red or big. Use an before orange or old.","tasks":[{"prompt":"Make a label for a red ball. Start with It.","words":["It","is","a","red","ball."],"answer":"It is a red ball.","full":"It is a red ball.","hint":"Start with It is. Add a red ball.","explain":"A red ball. A comes before the word red.","scene":"ball"},{"prompt":"Make a label for an orange kite. Start with It.","words":["It","is","an","orange","kite."],"answer":"It is an orange kite.","full":"It is an orange kite.","hint":"Start with It is. Add an orange kite.","explain":"An orange kite. An comes before orange.","scene":"girl"},{"prompt":"Make a label for a big train. Start with It.","words":["It","is","a","big","train."],"answer":"It is a big train.","full":"It is a big train.","hint":"Start with It is. Add a big train.","explain":"A big train. A comes before big.","scene":"boy"},{"prompt":"Make a label for an old car. Start with It.","words":["It","is","an","old","car."],"answer":"It is an old car.","full":"It is an old car.","hint":"Start with It is. Add an old car.","explain":"An old car. An comes before old.","scene":"boy"},{"prompt":"Make a label for a new doll. Start with It.","words":["It","is","a","new","doll."],"answer":"It is a new doll.","full":"It is a new doll.","hint":"Start with It is. Add a new doll.","explain":"A new doll. A comes before new.","scene":"girl"}]},{"id":"y1-river","title":"Classroom River","topic":"Classroom instructions","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"subtitle":"Help your class get ready","guide":"Put the word blocks in order. Each helpful instruction launches a boat!","taskLabel":"Boat launched","reminder":"A helpful instruction can end with please.","tasks":[{"prompt":"Ask your friend to open a book. Start with Open.","words":["Open","your","book,","please."],"answer":"Open your book, please.","full":"Open your book, please.","hint":"Start with Open. Add your book, then please.","explain":"Open your book, please. This is a helpful classroom instruction.","scene":"boy"},{"prompt":"Ask your friend to close a bag. Start with Close.","words":["Close","your","bag,","please."],"answer":"Close your bag, please.","full":"Close your bag, please.","hint":"Start with Close. Add your bag, then please.","explain":"Close your bag, please. Close tells your friend what to do.","scene":"girl"},{"prompt":"Ask for a pencil. Start with Pass.","words":["Pass","me","a","pencil,","please."],"answer":"Pass me a pencil, please.","full":"Pass me a pencil, please.","hint":"Start with Pass me. Add a pencil, then please.","explain":"Pass me a pencil, please. Please makes your request polite.","scene":"friends"},{"prompt":"Ask your friend to sit down. Start with Sit.","words":["Sit","down,","please."],"answer":"Sit down, please.","full":"Sit down, please.","hint":"Start with Sit. Then add down, and please.","explain":"Sit down, please. This tells your friend what to do.","scene":"boy"},{"prompt":"Ask your friend to look at a kite. Start with Look.","words":["Look","at","the","kite,","please."],"answer":"Look at the kite, please.","full":"Look at the kite, please.","hint":"Start with Look at. Add the kite, then please.","explain":"Look at the kite, please. Look at tells your friend where to look.","scene":"girl"}]},{"id":"y1-mine","title":"Pet Mine","topic":"I like · I do not like","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"subtitle":"Find a gem for each pet","guide":"Tap the word block that matches the story. Collect a pet gem!","taskLabel":"Pet gem found","reminder":"Like tells us what you enjoy. Do not like tells us what you do not enjoy.","tasks":[{"prompt":"Hana likes cats. She says: I ___ cats.","options":["like","do not like"],"answer":"like","full":"I like cats.","hint":"Hana likes cats. Choose like.","explain":"I like cats means Hana enjoys cats.","scene":"girl"},{"prompt":"Dan does not like snakes. He says: I ___ snakes.","options":["like","do not like"],"answer":"do not like","full":"I do not like snakes.","hint":"Dan does not like snakes. Choose do not like.","explain":"I do not like snakes tells us how Dan feels.","scene":"boy"},{"prompt":"May likes ducks. She says: I ___ ducks.","options":["like","do not like"],"answer":"like","full":"I like ducks.","hint":"May likes ducks. Choose like.","explain":"I like ducks means May enjoys ducks.","scene":"girl"},{"prompt":"Ben does not like rats. He says: I ___ rats.","options":["like","do not like"],"answer":"do not like","full":"I do not like rats.","hint":"Ben does not like rats. Choose do not like.","explain":"I do not like rats tells us how Ben feels.","scene":"boy"},{"prompt":"You enjoy dogs. Choose your words: I ___ dogs.","options":["do not like","like"],"answer":"like","full":"I like dogs.","hint":"You enjoy dogs. Say: I like dogs.","explain":"I like dogs tells people what you enjoy.","scene":"friends"}]},{"id":"y1-portal","title":"Lunchbox Portal","topic":"Lunchbox · have got","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"subtitle":"Pack lunch for the journey","guide":"Tap a word portal. Choose the words that match each lunchbox!","taskLabel":"Lunchbox packed","reminder":"Have got tells us what is in a lunchbox. Have not got tells us what is missing.","tasks":[{"prompt":"An apple is in my lunchbox. I ___ an apple.","options":["have got","have not got"],"answer":"have got","full":"I have got an apple.","hint":"The apple is in the lunchbox. Say have got.","explain":"I have got an apple means I have an apple.","scene":"apple"},{"prompt":"There is no banana in my lunchbox. I ___ a banana.","options":["have got","have not got"],"answer":"have not got","full":"I have not got a banana.","hint":"The banana is missing. Say have not got.","explain":"I have not got a banana means I do not have a banana.","scene":"boy"},{"prompt":"We have some cheese. Have we got any cheese? Yes, we ___.","options":["have","have not"],"answer":"have","full":"Yes, we have.","hint":"The cheese is here. Say Yes, we have.","explain":"Yes, we have answers the question about the cheese.","scene":"friends"},{"prompt":"We have no cake. Have we got any cake? No, we ___.","options":["have","have not"],"answer":"have not","full":"No, we have not.","hint":"There is no cake. Say No, we have not.","explain":"No, we have not means we do not have cake.","scene":"friends"},{"prompt":"A sandwich is in my lunchbox. I have ___ a sandwich.","options":["got","get"],"answer":"got","full":"I have got a sandwich.","hint":"Use the words have got together.","explain":"I have got a sandwich tells us what is in the lunchbox.","scene":"girl"}]},{"id":"y1-rescue","title":"Pet Hideout","topic":"in · on · under","type":"rune","color":"#ff9c95","icon":"cat","x":42,"y":22,"subtitle":"Find the hidden pets","guide":"Read the clue. Tap a place word to help a pet get home!","taskLabel":"Pet found","reminder":"In means inside. On means on top. Under means below.","tasks":[{"prompt":"The cat is inside the box. The cat is ___ the box.","options":["in","on","under"],"answer":"in","full":"The cat is in the box.","hint":"Inside means in.","explain":"In the box means inside the box.","scene":"friends"},{"prompt":"The dog is on top of the bag. The dog is ___ the bag.","options":["under","on","in"],"answer":"on","full":"The dog is on the bag.","hint":"On top means on.","explain":"On the bag means on top of the bag.","scene":"friends"},{"prompt":"The frog is below the desk. The frog is ___ the desk.","options":["on","in","under"],"answer":"under","full":"The frog is under the desk.","hint":"Below means under.","explain":"Under the desk means below the desk.","scene":"friends"},{"prompt":"The rat is inside the bag. The rat is ___ the bag.","options":["under","in","on"],"answer":"in","full":"The rat is in the bag.","hint":"Inside means in.","explain":"In the bag means inside the bag.","scene":"friends"},{"prompt":"The cat is below the chair. The cat is ___ the chair.","options":["under","on","in"],"answer":"under","full":"The cat is under the chair.","hint":"Below means under.","explain":"Under the chair means below the chair.","scene":"friends"}]},{"id":"y1-castle","title":"Toy Castle","topic":"big · small · tall · short","type":"compare","color":"#e5b3f0","icon":"castle","x":89,"y":73,"subtitle":"Choose the right size","guide":"Look at the sizes. Tap the object that matches the words!","taskLabel":"Castle light switched on","reminder":"Look at both objects. Big and small tell us about size. Tall and short tell us about height.","tasks":[{"prompt":"Find the big chest.","answer":"big","full":"Chest B is big.","hint":"Look for the chest that takes up more space.","explain":"Chest B is big. Chest A is small.","objects":[{"id":"small","label":"Chest A","size":75},{"id":"big","label":"Chest B","size":150}],"objectType":"chest"},{"prompt":"Find the small chest.","answer":"small","full":"Chest A is small.","hint":"Look for the chest that takes up less space.","explain":"Chest A is small. Chest B is big.","objects":[{"id":"small","label":"Chest A","size":70},{"id":"big","label":"Chest B","size":142}],"objectType":"chest"},{"prompt":"Find the tall tower.","answer":"tall","full":"Tower B is tall.","hint":"Look for the tower that goes high up.","explain":"Tower B is tall. Tower A is short.","objects":[{"id":"short","label":"Tower A","size":75},{"id":"tall","label":"Tower B","size":150}],"objectType":"tower"},{"prompt":"Find the short tower.","answer":"short","full":"Tower B is short.","hint":"Look for the tower that does not go very high.","explain":"Tower B is short. Tower A is tall.","objects":[{"id":"tall","label":"Tower A","size":146},{"id":"short","label":"Tower B","size":75}],"objectType":"tower"},{"prompt":"Choose a big chest for the toys.","answer":"big","full":"Chest A is big.","hint":"Find the chest with more space for the toys.","explain":"Chest A is big. It has more space for toys.","objects":[{"id":"big","label":"Chest A","size":145},{"id":"small","label":"Chest B","size":72}],"objectType":"chest"}]}],"rules":[["shop","Meet your friends","My name is ... · I am seven.","Use these words to tell a friend your name and age.","My name is Hana. I am seven."],["bridge","His and her","His = a boy's · Her = a girl's","Use his or her to talk about a name or a favourite toy.","Her kite belongs to May. His ball belongs to Dan."],["train","Toy labels","a red ball · an orange kite","Use a before red. Use an before orange. Listen to the first sound of the next word.","It is an old car. It is a new doll."],["boat","Helpful instructions","Open ... · Close ... · Pass me ...","Tell a friend what to do. Add please to be polite.","Close your bag, please."],["pickaxe","What I like","I like ... · I do not like ...","Use these words to say what you enjoy.","I like cats. I do not like snakes."],["portal","My lunchbox","I have got ... · I have not got ...","Have got tells us what you have. Have not got tells us what is missing.","I have got an apple. I have not got a banana."],["cat","Where is the pet?","in = inside · on = on top · under = below","Use a place word to find the pet.","The cat is under the chair."],["castle","Sizes","big · small · tall · short","Big and small tell us about size. Tall and short tell us about height.","The chest is big. The tower is tall."]],"curriculum":{"document":"KSSR (Semakan 2017), SK, CEFR-aligned","title":"DSKP Bahasa Inggeris Tahun 1 — Primary Year 1 English Language Syllabus","url":"https://bpk.moe.gov.my/kurikulum/kssr/kssr-tahun-1/57-48-dskp-kssr-semakan-tahun-1-bahasa-inggeris-cefr-sk-v2/file","grammarPages":"Printed pages 50 and 55–57 (PDF pages 64 and 69–71)","learningStandards":["3.2.2: Read details in very simple phrases and sentences.","3.3.1: Enjoy simple digital word games.","4.2.1: Give a name or age through familiar fixed phrases.","4.2.3: Express likes and dislikes.","4.2.4: Name or describe familiar objects."],"note":"Original medium-challenge practice using the SK Year 1 syllabus language in playful contexts. Year 1 grammar is experienced through meaning, fixed phrases and enjoyment, with short choices, word blocks, audio and hints. This pack practises selected language; game points do not determine a DSKP performance level."}},"y2-low":{"year":2,"levelLabel":"Supported adventure · small steps","missions":[{"id":"y2l-market","title":"Counting Market","topic":"One or more · there is and there are","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"subtitle":"Count the village supplies","guide":"Tap a word block. Count the supplies for the village!","taskLabel":"Shop supplied","reminder":"Use There is for one thing. Use There are for two or more.","tasks":[{"prompt":"One cap is here. There ___ a cap.","options":["is","are"],"answer":"is","full":"There is a cap.","hint":"One cap: say There is a cap.","explain":"There is tells us about one cap."},{"prompt":"Two shoes are here. There ___ two shoes.","options":["is","are"],"answer":"are","full":"There are two shoes.","hint":"Two shoes: say There are two shoes.","explain":"There are tells us about more than one shoe."},{"prompt":"One parrot is in the room. ___ a parrot.","options":["There are","There's"],"answer":"There's","full":"There's a parrot.","hint":"There's means There is.","explain":"There's a parrot tells us about one parrot."},{"prompt":"We want to count the hats. How ___ hats are there?","options":["old","many"],"answer":"many","full":"How many hats are there?","hint":"Ask How many? to count things.","explain":"How many hats are there? asks for the number of hats."},{"prompt":"Count the cars: car, car, car. There are ___ cars.","options":["two","three"],"answer":"three","full":"There are three cars.","hint":"Count each car: one, two, three.","explain":"There are three cars. Cars is the word for more than one car."}]},{"id":"y2l-bridge","title":"Weekend Bridge","topic":"Do you? · yes and no","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"subtitle":"Ask about free time","guide":"Tap a word block. Ask about free time to build the bridge!","taskLabel":"Bridge block added","reminder":"Do you? asks about a routine. Reply Yes, I do or No, I don't.","tasks":[{"prompt":"You play tennis on Sundays. Do you play tennis on Sundays? Yes, I ___.","options":["do","don't"],"answer":"do","full":"Yes, I do.","hint":"You play tennis. Answer Yes, I do.","explain":"Yes, I do answers the question about your routine."},{"prompt":"You do not watch TV on Mondays. Do you watch TV on Mondays? No, I ___.","options":["do","don't"],"answer":"don't","full":"No, I don't.","hint":"You do not watch TV. Answer No, I don't.","explain":"No, I don't tells us that you do not do this activity."},{"prompt":"Complete the routine question: ___ you play football on Saturdays?","options":["Do","Is"],"answer":"Do","full":"Do you play football on Saturdays?","hint":"Start the question with Do you.","explain":"Do you play football on Saturdays? asks about a routine."},{"prompt":"You ride a bike at the weekend. Do you ride a bike at the weekend? Yes, I ___.","options":["don't","do"],"answer":"do","full":"Yes, I do.","hint":"You ride a bike. Answer Yes, I do.","explain":"Yes, I do means that this is your weekend activity."},{"prompt":"You do not play the piano on Fridays. Do you play the piano on Fridays? ___","options":["No, I don't.","Yes, I do."],"answer":"No, I don't.","full":"No, I don't.","hint":"You do not play the piano. Choose No, I don't.","explain":"No, I don't matches the routine in the clue."}]},{"id":"y2l-train","title":"Free-time Train","topic":"I play · on days of the week","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"subtitle":"Make a free-time plan","guide":"Tap the word carriages in order. Tell a friend your plan!","taskLabel":"Train journey completed","reminder":"Use on with a day. Start your sentence with I.","tasks":[{"prompt":"You play football every Monday. Make your sentence. Start with I.","words":["I","play","football","on","Mondays."],"answer":"I play football on Mondays.","full":"I play football on Mondays.","hint":"Start with I play. Add football on Mondays.","explain":"I play football on Mondays tells us your weekly activity."},{"prompt":"You watch TV every Friday. Make your sentence. Start with I.","words":["I","watch","TV","on","Fridays."],"answer":"I watch TV on Fridays.","full":"I watch TV on Fridays.","hint":"Start with I watch. Add TV on Fridays.","explain":"On Fridays tells us when you watch TV."},{"prompt":"You ride a bike every Sunday. Make your sentence. Start with I.","words":["I","ride","a","bike","on","Sundays."],"answer":"I ride a bike on Sundays.","full":"I ride a bike on Sundays.","hint":"Start with I ride. Add a bike on Sundays.","explain":"I ride a bike on Sundays tells us your weekly activity."},{"prompt":"You play tennis every Tuesday. Make your sentence. Start with I.","words":["I","play","tennis","on","Tuesdays."],"answer":"I play tennis on Tuesdays.","full":"I play tennis on Tuesdays.","hint":"Start with I play. Add tennis on Tuesdays.","explain":"On Tuesdays tells us when you play tennis."},{"prompt":"You play the piano every Saturday. Make your sentence. Start with I.","words":["I","play","the","piano","on","Saturdays."],"answer":"I play the piano on Saturdays.","full":"I play the piano on Saturdays.","hint":"Start with I play. Add the piano on Saturdays.","explain":"I play the piano on Saturdays tells us your weekly activity."}]},{"id":"y2l-river","title":"Clothes River","topic":"is wearing · clothes and colours","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"subtitle":"Dress for the journey","guide":"Put the word blocks in order. Describe the clothes to launch a boat!","taskLabel":"Boat launched","reminder":"Say is wearing to tell us about clothes someone has on now.","tasks":[{"prompt":"Amir has a red cap on. Describe his clothes. Start with Amir.","words":["Amir","is","wearing","a","red","cap."],"answer":"Amir is wearing a red cap.","full":"Amir is wearing a red cap.","hint":"Start with Amir is wearing. Add a red cap.","explain":"Amir is wearing a red cap tells us what he has on now."},{"prompt":"Hana has a blue jacket on. Describe her clothes. Start with Hana.","words":["Hana","is","wearing","a","blue","jacket."],"answer":"Hana is wearing a blue jacket.","full":"Hana is wearing a blue jacket.","hint":"Start with Hana is wearing. Add a blue jacket.","explain":"Hana is wearing a blue jacket tells us about her clothes."},{"prompt":"A girl has a green skirt on. Describe her clothes. Start with She.","words":["She","is","wearing","a","green","skirt."],"answer":"She is wearing a green skirt.","full":"She is wearing a green skirt.","hint":"Start with She is wearing. Add a green skirt.","explain":"She is wearing a green skirt tells us what the girl has on."},{"prompt":"A boy has blue shoes on. Describe his clothes. Start with He.","words":["He","is","wearing","blue","shoes."],"answer":"He is wearing blue shoes.","full":"He is wearing blue shoes.","hint":"Start with He is wearing. Add blue shoes.","explain":"He is wearing blue shoes tells us what the boy has on."},{"prompt":"Mia has a warm sweater on. Describe her clothes. Start with Mia.","words":["Mia","is","wearing","a","warm","sweater."],"answer":"Mia is wearing a warm sweater.","full":"Mia is wearing a warm sweater.","hint":"Start with Mia is wearing. Add a warm sweater.","explain":"Mia is wearing a warm sweater tells us about her clothes."}]},{"id":"y2l-mine","title":"Ability Mine","topic":"can · can't","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"subtitle":"Discover what friends can do","guide":"Read the clue. Tap a word block to find an ability gem!","taskLabel":"Ability gem found","reminder":"Can means able to do it. Can't means not able to do it.","tasks":[{"prompt":"Dan can swim. Dan says: I ___ swim.","options":["can","can't"],"answer":"can","full":"I can swim.","hint":"Dan can swim. Choose can.","explain":"I can swim tells us that Dan is able to swim."},{"prompt":"The robot cannot fly. It says: I ___ fly.","options":["can","can't"],"answer":"can't","full":"I can't fly.","hint":"Cannot and can't mean the same thing.","explain":"I can't fly tells us that the robot is not able to fly."},{"prompt":"Mia can skip. She ___ skip.","options":["can't","can"],"answer":"can","full":"She can skip.","hint":"Mia is able to skip. Choose can.","explain":"She can skip tells us about Mia's ability."},{"prompt":"Ben can run. Can you run, Ben? Yes, I ___.","options":["can","can't"],"answer":"can","full":"Yes, I can.","hint":"Ben can run. Answer Yes, I can.","explain":"Yes, I can answers the question about running."},{"prompt":"Hana cannot dance. Can you dance, Hana? No, I ___.","options":["can","can't"],"answer":"can't","full":"No, I can't.","hint":"Hana cannot dance. Answer No, I can't.","explain":"No, I can't tells us that Hana is not able to dance."}]},{"id":"y2l-portal","title":"Dressing Portal","topic":"this · these · clothes questions","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"subtitle":"Choose clothes for the trip","guide":"Tap a word portal. Choose words for one item or more!","taskLabel":"Clothes portal opened","reminder":"Use this with one cap. Use these with shoes or socks.","tasks":[{"prompt":"One cap is here. Do you like ___ cap?","options":["this","these"],"answer":"this","full":"Do you like this cap?","hint":"One cap: use this cap.","explain":"This cap means one cap."},{"prompt":"Two shoes are here. Do you like ___ shoes?","options":["this","these"],"answer":"these","full":"Do you like these shoes?","hint":"Two shoes: use these shoes.","explain":"These shoes means more than one shoe."},{"prompt":"I like these socks. Do you like these socks? Yes, I ___.","options":["do","don't"],"answer":"do","full":"Yes, I do.","hint":"You like the socks. Answer Yes, I do.","explain":"Yes, I do tells us that you like the socks."},{"prompt":"I do not like this hat. Do you like this hat? No, I ___.","options":["do","don't"],"answer":"don't","full":"No, I don't.","hint":"You do not like the hat. Answer No, I don't.","explain":"No, I don't tells us that you do not like the hat."},{"prompt":"Ali is wearing a blue jacket. Is he wearing a blue jacket? Yes, he ___.","options":["is","isn't"],"answer":"is","full":"Yes, he is.","hint":"The blue jacket matches. Answer Yes, he is.","explain":"Yes, he is confirms that Ali is wearing a blue jacket."}]},{"id":"y2l-rescue","title":"Lost-and-Found Hideout","topic":"Where's? · Where are? · in","type":"rune","color":"#ff9c95","icon":"cat","x":42,"y":22,"subtitle":"Find the missing things","guide":"Read the clue. Tap the words to find the missing things!","taskLabel":"Lost item found","reminder":"Ask Where's? for one thing. Ask Where are? for more than one.","tasks":[{"prompt":"One book is in the bag. ___ the book?","options":["Where's","Where are"],"answer":"Where's","full":"Where's the book?","hint":"One book: ask Where's the book?","explain":"Where's means Where is. Use it to ask about one book."},{"prompt":"Two hats are in the box. ___ the hats?","options":["Where's","Where are"],"answer":"Where are","full":"Where are the hats?","hint":"Two hats: ask Where are the hats?","explain":"Where are asks about the place of more than one hat."},{"prompt":"Where's the cap? The cap is in the bag. ___ in the bag.","options":["They're","It's"],"answer":"It's","full":"It's in the bag.","hint":"One cap: say It's in the bag.","explain":"It's means It is. It takes the place of the cap."},{"prompt":"Where are the shoes? The shoes are in the box. ___ in the box.","options":["It's","They're"],"answer":"They're","full":"They're in the box.","hint":"Two shoes: say They're in the box.","explain":"They're means They are. They takes the place of the shoes."},{"prompt":"The map is inside the bag. The map is ___ the bag.","options":["is","in"],"answer":"in","full":"The map is in the bag.","hint":"Inside means in.","explain":"In the bag means inside the bag."}]},{"id":"y2l-castle","title":"Beach Castle","topic":"Let's · friendly replies","type":"rune","color":"#e5b3f0","icon":"castle","x":89,"y":73,"subtitle":"Make a plan with friends","guide":"Read the clue. Tap a suggestion or reply to light the castle!","taskLabel":"Castle light switched on","reminder":"Let's suggests an activity together. Say Good idea when you like the plan.","tasks":[{"prompt":"Choose the word to make a suggestion: ___ read a book.","options":["Let's","There"],"answer":"Let's","full":"Let's read a book.","hint":"Start your suggestion with Let's.","explain":"Let's read a book suggests reading together."},{"prompt":"Choose the activity that uses a camera: Let's ___.","options":["take a photo","make a sandcastle"],"answer":"take a photo","full":"Let's take a photo.","hint":"A camera helps us take a photo.","explain":"Let's take a photo suggests an activity with a camera."},{"prompt":"Your friend says, Let's play tennis. You like the idea. Say: ___","options":["Good idea.","I'm not sure."],"answer":"Good idea.","full":"Good idea.","hint":"You like the plan. Say Good idea.","explain":"Good idea tells your friend that you like the suggestion."},{"prompt":"Your friend says, Let's dance. You do not want to dance. Say: ___","options":["Good idea.","Sorry, I don't want to."],"answer":"Sorry, I don't want to.","full":"Sorry, I don't want to.","hint":"You do not want to dance. Say Sorry, I don't want to.","explain":"Sorry, I don't want to politely says that you do not want this activity."},{"prompt":"Choose the activity that uses paper and paints: Let's ___.","options":["catch a fish","paint a picture"],"answer":"paint a picture","full":"Let's paint a picture.","hint":"Use paper and paints to paint a picture.","explain":"Let's paint a picture suggests an activity with paper and paints."}]}],"rules":[["shop","Count the supplies","There is one ... · There are two ...","Use is for one thing. Use are for two or more.","There is a cap. There are two shoes."],["bridge","Ask about free time","Do you ...? · Yes, I do. · No, I don't.","Use these words to ask and answer about a routine.","Do you play tennis on Sundays? Yes, I do."],["train","Your weekly plan","I play ... on Mondays.","Use on with a day to tell a friend when you do an activity.","I ride a bike on Sundays."],["boat","Clothes now","He is wearing ... · She is wearing ...","Wearing tells us about clothes someone has on now.","She is wearing a green skirt."],["pickaxe","What you can do","I can ... · I can't ...","Can means able to do it. Cannot and can't mean the same thing.","I can swim. I can't fly."],["portal","One item or more","this cap · these shoes","Use this with one item. Use these with more than one item.","Do you like this cap? Do you like these shoes?"],["cat","Find the things","Where's ...? · Where are ...?","Use It's for one thing. Use They're for more than one. In means inside.","Where are the shoes? They're in the box."],["castle","Make a friendly plan","Let's ... · Good idea.","Use Let's to suggest an activity together. Say Good idea when you like the plan.","Let's paint a picture. Good idea."]],"curriculum":{"document":"KSSR (Semakan 2017), SK, CEFR-aligned, KPM BPK","title":"DSKP Bahasa Inggeris Tahun 2 — Primary Year 2 English Language Syllabus (SK)","url":"https://bpk.moe.gov.my/kurikulum/kssr/kssr-tahun-2/96-50-dskp-kssr-semakan-tahun-2-bahasa-inggeris-cefr-sk-v2/file","grammarPages":"Printed p. 48 (meaning-led grammar); pp. 54–56 (routines, counting, clothes, ability, suggestions, location). PDF pp. 62, 68–70.","learningStandards":["3.2.1–3.2.2, p. 36: Understand simple sentences and their details.","3.3.1, p. 36: Enjoy sentence-level digital games.","4.2.2 and 4.2.4, p. 41: Ability and object descriptions.","4.3.1 and 4.3.3, p. 41: Guided punctuation and sentence formation."],"note":"Original supported practice for 2B/2K. Short choices, familiar phrases and direct clues keep the focus on meaning and enjoyment. Selected grammar practice only; scores are not PBD levels or full DSKP assessment."}},"y2-challenge":{"year":2,"levelLabel":"Challenge adventure · read the clues","missions":[{"id":"y2c-market","title":"Market Explorer","topic":"Count and check · there is and there are","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"subtitle":"Read the market clues","guide":"Read the list. Tap the word block that matches the supplies!","taskLabel":"Shop supplied","reminder":"Match the words to the number. One item needs is; two or more need are.","tasks":[{"prompt":"Market list: one jacket, two caps. There ___ two caps.","options":["is","am","are"],"answer":"are","full":"There are two caps.","hint":"The clue says two caps. Choose the words for more than one.","explain":"There are matches two caps. There is would describe one cap."},{"prompt":"Market list: three hats, no shoes. Are there any shoes? No, there ___.","options":["are","aren't","is"],"answer":"aren't","full":"No, there aren't.","hint":"Read the shoes part of the list. There are no shoes.","explain":"No, there aren't matches the question and the empty shoes list."},{"prompt":"Only one parrot is in the tower. Complete the yes-or-no question: ___ a parrot in the tower?","options":["Are there","How many","Is there"],"answer":"Is there","full":"Is there a parrot in the tower?","hint":"The question is about one parrot. Start with Is there.","explain":"Is there a parrot? asks whether one parrot is there."},{"prompt":"Room list: one robot, four cars. How many cars are there? There are ___.","options":["one robot","four cars","a car"],"answer":"four cars","full":"There are four cars.","hint":"Count the cars, not the robot.","explain":"How many cars? asks for the car count. The list has four cars."},{"prompt":"Box list: two books and one map. ___ a map in the box.","options":["There are","There aren't","There's"],"answer":"There's","full":"There's a map in the box.","hint":"The map is one item. Choose the words for one.","explain":"There's means There is. It matches one map."}]},{"id":"y2c-bridge","title":"Routine Bridge","topic":"Do you? · read a weekly plan","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"subtitle":"Ask the right routine question","guide":"Read the plan. Tap an answer that matches the day and activity!","taskLabel":"Bridge block added","reminder":"Read the whole clue before answering. Do you? uses Yes, I do or No, I don't.","tasks":[{"prompt":"Sara: I ride a bike on Sundays. Do you ride a bike on Sundays, Sara? ___","options":["No, I don't.","Yes, I can.","Yes, I do."],"answer":"Yes, I do.","full":"Yes, I do.","hint":"Sara rides a bike on Sundays. The question starts with Do you.","explain":"Yes, I do matches both the routine and the Do you question."},{"prompt":"Dan: I play tennis on Saturdays. I do not play tennis on Mondays. Do you play tennis on Mondays, Dan? ___","options":["Yes, I do.","No, I don't.","No, I can't."],"answer":"No, I don't.","full":"No, I don't.","hint":"Check Monday, not Saturday.","explain":"No, I don't matches Dan's Monday routine."},{"prompt":"Mia: I watch TV on Fridays. Ask Mia about her Friday routine: ___ you watch TV on Fridays?","options":["Is","Do","Are"],"answer":"Do","full":"Do you watch TV on Fridays?","hint":"Use Do you to ask about this free-time routine.","explain":"Do you watch TV on Fridays? asks about Mia's weekly activity."},{"prompt":"Ali: I read a book on Tuesdays. Do you read a book on Tuesdays, Ali? Yes, I ___.","options":["am","can","do"],"answer":"do","full":"Yes, I do.","hint":"Match Do you with Yes, I do.","explain":"Yes, I do confirms that reading is Ali's Tuesday activity."},{"prompt":"Tim: I ride a bike at the weekend. I do not watch TV at the weekend. Do you watch TV at the weekend, Tim? No, I ___.","options":["don't","isn't","can't"],"answer":"don't","full":"No, I don't.","hint":"Check the TV clue, not the bike clue.","explain":"No, I don't matches the activity in the question."}]},{"id":"y2c-train","title":"Weekly-plan Train","topic":"Free-time sentences · on and at","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"subtitle":"Turn clues into a plan","guide":"Tap the word carriages in order. Turn each plan into a sentence!","taskLabel":"Train journey completed","reminder":"Use on with days, such as Mondays. Use at in at the weekend.","tasks":[{"prompt":"Your plan says: tennis, every Monday. Tell a friend. Start with I.","words":["I","play","tennis","on","Mondays."],"answer":"I play tennis on Mondays.","full":"I play tennis on Mondays.","hint":"Begin I play. Put the day after on.","explain":"I play tennis on Mondays gives the activity and the repeated day."},{"prompt":"You read a book each Friday. Tell a friend when. Start with I.","words":["I","read","a","book","on","Fridays."],"answer":"I read a book on Fridays.","full":"I read a book on Fridays.","hint":"Begin I read. Put on Fridays at the end.","explain":"On Fridays tells your friend which day this happens."},{"prompt":"Every Sunday is your bike day. Tell a friend your routine. Start with I.","words":["I","ride","a","bike","on","Sundays."],"answer":"I ride a bike on Sundays.","full":"I ride a bike on Sundays.","hint":"Begin I ride. Put the activity before the day.","explain":"I ride a bike on Sundays turns the weekly plan into a sentence."},{"prompt":"The piano is your activity every Saturday. Make your sentence. Start with I.","words":["I","play","the","piano","on","Saturdays."],"answer":"I play the piano on Saturdays.","full":"I play the piano on Saturdays.","hint":"Begin I play. Keep the piano together.","explain":"I play the piano on Saturdays gives the activity and the day."},{"prompt":"Your weekend activity is watching TV. Tell a friend. Start with I.","words":["I","watch","TV","at","the","weekend."],"answer":"I watch TV at the weekend.","full":"I watch TV at the weekend.","hint":"Begin I watch TV. Finish with at the weekend.","explain":"At the weekend tells us when you watch TV."}]},{"id":"y2c-river","title":"Clothes-check River","topic":"Wearing · statements and questions","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"subtitle":"Read clothes clues","guide":"Put the word blocks in order. Describe or check the clothes!","taskLabel":"Boat launched","reminder":"Describe clothes with is wearing. Start a clothes question with Is he or Is she.","tasks":[{"prompt":"Amir has a red cap on his head. Describe what he is wearing. Start with Amir.","words":["Amir","is","wearing","a","red","cap."],"answer":"Amir is wearing a red cap.","full":"Amir is wearing a red cap.","hint":"Begin Amir is wearing. Put the colour before cap.","explain":"Amir is wearing a red cap describes the clothes in the clue."},{"prompt":"Nia is a girl with a green skirt on. Describe her clothes. Start with She.","words":["She","is","wearing","a","green","skirt."],"answer":"She is wearing a green skirt.","full":"She is wearing a green skirt.","hint":"She replaces Nia. Begin She is wearing.","explain":"She is wearing a green skirt describes Nia's clothes."},{"prompt":"Dan is a boy with blue shoes on his feet. Describe his clothes. Start with He.","words":["He","is","wearing","blue","shoes."],"answer":"He is wearing blue shoes.","full":"He is wearing blue shoes.","hint":"He replaces Dan. Begin He is wearing.","explain":"He is wearing blue shoes describes Dan's clothes."},{"prompt":"Ben is a boy. You want to check if his T-shirt is blue. Build a question. Start with Is.","words":["Is","he","wearing","a","blue","T-shirt?"],"answer":"Is he wearing a blue T-shirt?","full":"Is he wearing a blue T-shirt?","hint":"Begin Is he wearing. Finish the question with a blue T-shirt?","explain":"Is he wearing a blue T-shirt? asks someone to check Ben's clothes."},{"prompt":"Mia is a girl. You want to check if she has a warm jacket on. Build a question. Start with Is.","words":["Is","she","wearing","a","warm","jacket?"],"answer":"Is she wearing a warm jacket?","full":"Is she wearing a warm jacket?","hint":"Begin Is she wearing. Finish with a warm jacket?","explain":"Is she wearing a warm jacket? asks someone to check Mia's clothes."}]},{"id":"y2c-mine","title":"Robot Ability Mine","topic":"can · can't · check the skill card","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"subtitle":"Match skills to the clue","guide":"Read the skill card. Tap the answer that matches the ability!","taskLabel":"Ability gem found","reminder":"Check the activity in the question. Can means able; can't means not able.","tasks":[{"prompt":"Robot card: swim yes; fly no. The robot ___ swim.","options":["can't","is","can"],"answer":"can","full":"The robot can swim.","hint":"Read the swim part of the card.","explain":"The robot can swim matches swim yes."},{"prompt":"Mia: I can run. I can't skip. Can you skip, Mia? ___","options":["Yes, I can.","No, I can't.","No, I don't."],"answer":"No, I can't.","full":"No, I can't.","hint":"The question asks about skipping, not running.","explain":"No, I can't matches Mia's skipping ability."},{"prompt":"Amir: I can dance. I can't fly. Amir ___ dance.","options":["is","can't","can"],"answer":"can","full":"Amir can dance.","hint":"Choose the words for the dance clue.","explain":"Amir can dance matches the first part of his skill card."},{"prompt":"Nia is a girl. Her card says: jump yes; swim no. She ___ swim.","options":["can","are","can't"],"answer":"can't","full":"She can't swim.","hint":"Check swim, not jump.","explain":"She can't swim matches swim no."},{"prompt":"Ben: I can stand on one leg. Ask Ben about this ability: ___ you stand on one leg?","options":["Are","Can","Is"],"answer":"Can","full":"Can you stand on one leg?","hint":"Start an ability question with Can you.","explain":"Can you stand on one leg? asks about Ben's ability."}]},{"id":"y2c-portal","title":"Clothes-choice Portal","topic":"this · these · read and reply","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"subtitle":"Check the clothes together","guide":"Tap a word portal. Check the item, colour and reply!","taskLabel":"Clothes portal opened","reminder":"Use this for one item and these for more than one. Check colours before you reply.","tasks":[{"prompt":"Shop labels: one cap, two socks. Ask about the cap: Do you like ___ cap?","options":["these","they","this"],"answer":"this","full":"Do you like this cap?","hint":"The cap is one item.","explain":"This cap matches the one cap on the shop list."},{"prompt":"Shop labels: one cap, two socks. Ask about the socks: Do you like ___ socks?","options":["this","these","it"],"answer":"these","full":"Do you like these socks?","hint":"The socks are more than one item.","explain":"These socks matches the two socks on the shop list."},{"prompt":"Amir has a green jacket on. Is he wearing a blue jacket? ___","options":["Yes, he is.","No, he can't.","No, he isn't."],"answer":"No, he isn't.","full":"No, he isn't.","hint":"The question says blue. The clue says green.","explain":"No, he isn't is the reply because Amir's jacket is green."},{"prompt":"Hana has a red skirt on. Is she wearing a red skirt? Yes, she ___.","options":["isn't","is","are"],"answer":"is","full":"Yes, she is.","hint":"The colour and the clothing both match.","explain":"Yes, she is confirms the clothes in the clue."},{"prompt":"Mia: I like this cap. I do not like these shoes. Do you like these shoes, Mia? ___","options":["No, I don't.","Yes, I do.","No, I can't."],"answer":"No, I don't.","full":"No, I don't.","hint":"Read the shoes clue. The question is not about the cap.","explain":"No, I don't matches how Mia feels about the shoes."}]},{"id":"y2c-rescue","title":"Lost-item Hideout","topic":"Where's? · Where are? · match the place","type":"rune","color":"#ff9c95","icon":"cat","x":42,"y":22,"subtitle":"Find things from a list","guide":"Read both clues. Tap the words that find the right item!","taskLabel":"Lost item found","reminder":"One item uses Where's and It's. More than one uses Where are and They're.","tasks":[{"prompt":"Bag list: one book and two caps. Ask about the book: ___ the book?","options":["Where are","They're","Where's"],"answer":"Where's","full":"Where's the book?","hint":"The book is one item.","explain":"Where's the book? asks about the place of the one book."},{"prompt":"Bag list: one book and two caps. Ask about the caps: ___ the caps?","options":["Where's","Where are","It's"],"answer":"Where are","full":"Where are the caps?","hint":"The caps are more than one item.","explain":"Where are the caps? asks about the place of the two caps."},{"prompt":"One blue book is in a red bag. Two green books are in a black bag. Where's the blue book? ___","options":["They're in the red bag.","It's in the black bag.","It's in the red bag."],"answer":"It's in the red bag.","full":"It's in the red bag.","hint":"Find the blue book. There is only one blue book.","explain":"It's in the red bag uses It's for one book and matches its bag."},{"prompt":"One red cap is in a green box. Two red shoes are in a blue bag. Where are the shoes? ___","options":["They're in the green box.","They're in the blue bag.","It's in the blue bag."],"answer":"They're in the blue bag.","full":"They're in the blue bag.","hint":"Find the shoes. Use the words for more than one.","explain":"They're in the blue bag matches both the two shoes and their place."},{"prompt":"One map is in the bag. Where's the map? ___ in the bag.","options":["It's","There are","They're"],"answer":"It's","full":"It's in the bag.","hint":"Answer about the one map.","explain":"It's in the bag uses It for the one map."}]},{"id":"y2c-castle","title":"Beach-plan Castle","topic":"Let's · choose a matching reply","type":"rune","color":"#e5b3f0","icon":"castle","x":89,"y":73,"subtitle":"Plan an adventure together","guide":"Read the clue. Tap the suggestion or reply that matches the plan!","taskLabel":"Castle light switched on","reminder":"Let's suggests a plan. Good idea agrees. I'm not sure means you have not decided.","tasks":[{"prompt":"We have sand and a bucket. Choose the activity that uses both: Let's ___.","options":["read a book","make a sandcastle","play the piano"],"answer":"make a sandcastle","full":"Let's make a sandcastle.","hint":"Think about what you can make with sand and a bucket.","explain":"Let's make a sandcastle matches the materials in the clue."},{"prompt":"Paper and paints are ready. Choose the matching suggestion: Let's ___.","options":["take a photo","listen to music","paint a picture"],"answer":"paint a picture","full":"Let's paint a picture.","hint":"Which activity uses paper and paints?","explain":"Let's paint a picture matches the materials that are ready."},{"prompt":"Your friend says, Let's go swimming. You want to swim too. Choose your reply: ___","options":["I'm not sure.","Good idea.","Sorry, I don't want to."],"answer":"Good idea.","full":"Good idea.","hint":"You both want to swim. Choose the reply that agrees.","explain":"Good idea tells your friend that you want to follow the plan."},{"prompt":"Your friend says, Let's play tennis. You do not want to play. Choose your reply: ___","options":["Sorry, I don't want to.","Good idea.","I'm not sure."],"answer":"Sorry, I don't want to.","full":"Sorry, I don't want to.","hint":"You have decided that you do not want to play.","explain":"Sorry, I don't want to politely declines the tennis plan."},{"prompt":"Your friend says, Let's read a book. You have not decided if you want to read. Choose your reply: ___","options":["Good idea.","Sorry, I don't want to.","I'm not sure."],"answer":"I'm not sure.","full":"I'm not sure.","hint":"Choose the reply that means you have not decided.","explain":"I'm not sure tells your friend that you have not decided."}]}],"rules":[["shop","Check the supplies","There is ... · There are ... · How many ...?","Read the count. Use is for one and are for two or more. Ask How many? for a number.","How many hats are there? There are three hats."],["bridge","Check the routine","Do you ...? · Yes, I do. · No, I don't.","Read the activity and the day. Match your reply to both.","Do you watch TV on Fridays? Yes, I do."],["train","Tell your weekly plan","on Mondays · at the weekend","Put the activity after I. Use on with a day and at in at the weekend.","I play the piano on Saturdays."],["boat","Describe or check clothes","She is wearing ... · Is she wearing ...?","A statement tells us about clothes. A question asks someone to check them.","Is he wearing a blue T-shirt?"],["pickaxe","Check an ability","Can you ...? · Yes, I can. · No, I can't.","Read the activity in the question. A friend may be able to do one activity but not another.","Can you skip? No, I can't."],["portal","Check one item or more","this cap · these socks · Is he wearing ...?","Use this for one and these for more than one. Check the colour before replying.","Is he wearing a red cap? Yes, he is."],["cat","Match the item and place","Where's / It's · Where are / They're","Find the correct item. Then match one or more and its place.","Where's the map? It's in the bag."],["castle","Match a plan and a reply","Let's ... · Good idea. · I'm not sure.","Agree with Good idea. Say I'm not sure if you have not decided. Decline politely with Sorry, I don't want to.","Let's take a photo. Good idea."]],"curriculum":{"document":"KSSR (Semakan 2017), SK, CEFR-aligned, KPM BPK","title":"DSKP Bahasa Inggeris Tahun 2 — Primary Year 2 English Language Syllabus (SK)","url":"https://bpk.moe.gov.my/kurikulum/kssr/kssr-tahun-2/96-50-dskp-kssr-semakan-tahun-2-bahasa-inggeris-cefr-sk-v2/file","grammarPages":"Printed p. 48 (meaning-led grammar); pp. 54–56 (routines, counting, clothes, ability, suggestions, location). PDF pp. 62, 68–70.","learningStandards":["3.2.1–3.2.2, p. 36: Understand simple sentences and their details.","3.3.1, p. 36: Enjoy sentence-level digital games.","4.2.2 and 4.2.4, p. 41: Ability and object descriptions.","4.3.1 and 4.3.3, p. 41: Guided punctuation and sentence formation."],"note":"Original medium/high practice for 2S. Context and meaning add challenge within Year 2 forms. Selected grammar practice only; scores are not PBD levels or full DSKP assessment."}},"y3-supported":{"year":3,"levelLabel":"Step-by-step adventure","missions":[{"id":"y3-market","title":"Counting Market","topic":"There is · there are · plurals","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"subtitle":"Count the village supplies","guide":"Tap the correct word block. Help the market count its supplies!","taskLabel":"Shop supplied","reminder":"There is goes with one thing. There are goes with more than one.","tasks":[{"prompt":"One apple is on the stall. There ___ one apple.","options":["is","are"],"answer":"is","full":"There is one apple.","hint":"One apple is one thing. Choose is.","explain":"There is one apple. Use is for one thing.","scene":"apple"},{"prompt":"Three bags are on the stall. There ___ three bags.","options":["is","are"],"answer":"are","full":"There are three bags.","hint":"Three bags are more than one. Choose are.","explain":"There are three bags. Use are for more than one thing.","scene":"friends"},{"prompt":"We have two boxes. There are two ___ here.","options":["box","boxes"],"answer":"boxes","full":"There are two boxes here.","hint":"More than one box: boxes.","explain":"Use boxes when there is more than one box.","scene":"friends"},{"prompt":"Two children visit the market. There are two ___.","options":["child","children"],"answer":"children","full":"There are two children.","hint":"One child. Two children.","explain":"Children is the word for more than one child.","scene":"friends"},{"prompt":"Two mice hide by the stall. There are two ___.","options":["mouse","mice"],"answer":"mice","full":"There are two mice.","hint":"One mouse. Two mice.","explain":"Mice is the word for more than one mouse.","scene":"friends"}]},{"id":"y3-bridge","title":"Friendship Bridge","topic":"he · she · they · his · her","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"subtitle":"Help your friends cross","guide":"Tap the correct pronoun block. Build a bridge for your friends!","taskLabel":"Bridge block added","reminder":"Use he for a boy, she for a girl, and they for two or more people.","tasks":[{"prompt":"Amir is a boy. ___ is my friend.","options":["He","She","They"],"answer":"He","full":"Amir is a boy. He is my friend.","hint":"Amir is a boy. Choose He.","explain":"He takes the place of Amir.","scene":"boy"},{"prompt":"Mei is a girl. ___ is reading.","options":["He","She","They"],"answer":"She","full":"Mei is a girl. She is reading.","hint":"Mei is a girl. Choose She.","explain":"She takes the place of Mei.","scene":"girl"},{"prompt":"Amir and Mei play together. ___ are friends.","options":["He","She","They"],"answer":"They","full":"Amir and Mei play together. They are friends.","hint":"Amir and Mei are two people. Choose They.","explain":"They takes the place of Amir and Mei.","scene":"friends"},{"prompt":"This cap belongs to Amir. It is ___ cap.","options":["his","her"],"answer":"his","full":"It is his cap.","hint":"The cap belongs to a boy. Choose his.","explain":"His cap means the cap belongs to Amir.","scene":"boy"},{"prompt":"This ruler belongs to Mei. It is ___ ruler.","options":["his","her"],"answer":"her","full":"It is her ruler.","hint":"The ruler belongs to a girl. Choose her.","explain":"Her ruler means the ruler belongs to Mei.","scene":"girl"}]},{"id":"y3-train","title":"Routine Train","topic":"Every day · simple present","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"subtitle":"Build a daily routine","guide":"Tap the word carriages in order. Build a routine to move the train!","taskLabel":"Train journey completed","reminder":"Use play with I or they. Use plays with he or she.","tasks":[{"prompt":"Tell us your morning routine. Start with I.","words":["I","eat","breakfast","every","day."],"answer":"I eat breakfast every day.","full":"I eat breakfast every day.","hint":"Start with I eat. Finish with every day.","explain":"Every day tells us this is a routine. Use eat after I.","scene":"boy"},{"prompt":"Tell us how Mei goes to school. Start with She.","words":["She","walks","to","school."],"answer":"She walks to school.","full":"She walks to school.","hint":"Start with She. Then put walks.","explain":"She walks to school. Use walks after she for a routine.","scene":"girl"},{"prompt":"Tell us about the friends. Start with They.","words":["They","play","football","every","day."],"answer":"They play football every day.","full":"They play football every day.","hint":"Start with They play. Finish with every day.","explain":"They play football every day. Use play after they.","scene":"ball"},{"prompt":"Amir always packs his bag. Start with He.","words":["He","always","packs","his","bag."],"answer":"He always packs his bag.","full":"He always packs his bag.","hint":"Start with He always. Put packs next.","explain":"Always means every time. Use packs after he.","scene":"boy"},{"prompt":"Tell us what your group does after school. Start with We.","words":["We","read","books","after","school."],"answer":"We read books after school.","full":"We read books after school.","hint":"Start with We read. Finish with after school.","explain":"We read books after school. Use read after we.","scene":"friends"}]},{"id":"y3-river","title":"Action River","topic":"Actions now · am · is · are","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"subtitle":"Build actions happening now","guide":"Put the word blocks in order. Build a boat with an action happening now!","taskLabel":"Boat launched","reminder":"For an action happening now, use am, is or are with an -ing word.","tasks":[{"prompt":"You are reading now. Start with I.","words":["I","am","reading","a","book."],"answer":"I am reading a book.","full":"I am reading a book.","hint":"Start with I am. Add reading a book.","explain":"I am reading a book. Use am with I.","scene":"boy"},{"prompt":"Mei is singing now. Start with She.","words":["She","is","singing","now."],"answer":"She is singing now.","full":"She is singing now.","hint":"Start with She is. Put singing next.","explain":"She is singing now. Use is with she.","scene":"girl"},{"prompt":"The boys are playing now. Start with They.","words":["They","are","playing","football."],"answer":"They are playing football.","full":"They are playing football.","hint":"Start with They are. Put playing next.","explain":"They are playing football. Use are with they.","scene":"ball"},{"prompt":"Amir is eating now. Start with He.","words":["He","is","eating","an","apple."],"answer":"He is eating an apple.","full":"He is eating an apple.","hint":"Start with He is. Add eating an apple.","explain":"He is eating an apple. Use is with he.","scene":"apple"},{"prompt":"Your group is drawing now. Start with We.","words":["We","are","drawing","now."],"answer":"We are drawing now.","full":"We are drawing now.","hint":"Start with We are. Put drawing next.","explain":"We are drawing now. Use are with we.","scene":"friends"}]},{"id":"y3-mine","title":"Yesterday Mine","topic":"Yesterday · simple past","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"subtitle":"Find words from the past","guide":"Tap the correct word block. Find a gem for each action from yesterday!","taskLabel":"Past gem found","reminder":"Yesterday is in the past. Play becomes played. Go becomes went.","tasks":[{"prompt":"Yesterday, I ___ a game.","options":["play","played"],"answer":"played","full":"Yesterday, I played a game.","hint":"Yesterday is in the past. Play becomes played.","explain":"Played tells us the action happened in the past.","scene":"boy"},{"prompt":"Yesterday, Mei ___ her grandma.","options":["visited","visit"],"answer":"visited","full":"Yesterday, Mei visited her grandma.","hint":"Visit becomes visited for the past.","explain":"Visited tells us Mei saw her grandma in the past.","scene":"girl"},{"prompt":"Yesterday, Amir ___ to the park.","options":["go","went"],"answer":"went","full":"Yesterday, Amir went to the park.","hint":"Go changes to went in the past.","explain":"Went is the past word for go.","scene":"boy"},{"prompt":"Last night, we ___ rice.","options":["ate","eat"],"answer":"ate","full":"Last night, we ate rice.","hint":"Eat changes to ate in the past.","explain":"Ate tells us the meal happened last night.","scene":"friends"},{"prompt":"Yesterday, they ___ a film.","options":["watch","watched"],"answer":"watched","full":"Yesterday, they watched a film.","hint":"Watch becomes watched for the past.","explain":"Watched tells us the action happened yesterday.","scene":"friends"}]},{"id":"y3-portal","title":"Linking Portal","topic":"and · or · but","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"subtitle":"Join the story blocks","guide":"Read the story clue. Tap a linking word to open the portal!","taskLabel":"Story portal opened","reminder":"And adds. Or gives a choice. But joins different or opposite ideas.","tasks":[{"prompt":"We need both things. Bring a pencil ___ a ruler.","options":["and","or","but"],"answer":"and","full":"Bring a pencil and a ruler.","hint":"We need both a pencil and a ruler. Use and.","explain":"And joins the two things we need.","scene":"friends"},{"prompt":"Choose one drink. Would you like milk ___ water?","options":["and","but","or"],"answer":"or","full":"Would you like milk or water?","hint":"You choose one drink. Use or.","explain":"Or gives you a choice between two drinks.","scene":"friends"},{"prompt":"Join these opposite ideas: I like cats, ___ I do not like snakes.","options":["or","but","and"],"answer":"but","full":"I like cats, but I do not like snakes.","hint":"One animal is liked. The other is not. Use but to show the difference.","explain":"But connects the different ideas about cats and snakes.","scene":"friends"},{"prompt":"Both friends are here. Amir ___ Mei are in the village.","options":["but","and","or"],"answer":"and","full":"Amir and Mei are in the village.","hint":"Both friends are here. Use and to name both.","explain":"And connects the names of the two friends.","scene":"friends"},{"prompt":"Join these surprising ideas: The box is small, ___ it is heavy.","options":["and","or","but"],"answer":"but","full":"The box is small, but it is heavy.","hint":"The box is small, yet it is heavy. Use but to show the surprise.","explain":"But shows the difference: the box is small, yet it is heavy.","scene":"friends"}]},{"id":"y3-rescue","title":"Animal Rescue","topic":"in · on · under · behind · between","type":"place","color":"#ff9c95","icon":"cat","x":42,"y":22,"subtitle":"Give the cat a safe place","guide":"Tap the cat, then tap its place. You can also drag the cat!","taskLabel":"Cat rescued","reminder":"Read the place word. In is inside. Behind is at the back. Between is in the middle.","tasks":[{"prompt":"The cat is in the box.","answer":"in","full":"The cat is in the box.","hint":"In means inside. Tap the inside of the box.","explain":"In the box means inside the box."},{"prompt":"The cat is on the table.","answer":"on","full":"The cat is on the table.","hint":"On means on top. Tap the table top.","explain":"On the table means on top of the table."},{"prompt":"The cat is under the table.","answer":"under","full":"The cat is under the table.","hint":"Under means below. Tap the space below the table.","explain":"Under the table means below the table."},{"prompt":"The cat is behind the tree.","answer":"behind","full":"The cat is behind the tree.","hint":"Behind means at the back. Tap the space behind the tree.","explain":"Behind the tree means at the back of the tree."},{"prompt":"The cat is between the rocks.","answer":"between","full":"The cat is between the rocks.","hint":"Between means in the middle of two things. Tap the space between the rocks.","explain":"Between the rocks means in the middle of the two rocks."}]},{"id":"y3-castle","title":"Size Castle","topic":"taller · shorter · bigger · smaller","type":"compare","color":"#e5b3f0","icon":"castle","x":89,"y":73,"subtitle":"Compare two objects","guide":"Look at both objects. Tap the one that matches the words!","taskLabel":"Castle light switched on","reminder":"Taller and shorter compare heights. Bigger and smaller compare sizes.","tasks":[{"prompt":"Choose the taller tower.","answer":"taller","full":"Tower B is taller than Tower A.","hint":"Look for the tower that is higher than the other.","explain":"Tower B is taller than Tower A.","objects":[{"id":"shorter","label":"Tower A","size":75},{"id":"taller","label":"Tower B","size":146}],"objectType":"tower"},{"prompt":"Choose the shorter tower.","answer":"shorter","full":"Tower A is shorter than Tower B.","hint":"Look for the tower that is lower than the other.","explain":"Tower A is shorter than Tower B.","objects":[{"id":"shorter","label":"Tower A","size":78},{"id":"taller","label":"Tower B","size":151}],"objectType":"tower"},{"prompt":"Choose the bigger chest.","answer":"bigger","full":"Chest A is bigger than Chest B.","hint":"Look for the chest that takes up more space.","explain":"Chest A is bigger than Chest B.","objects":[{"id":"bigger","label":"Chest A","size":145},{"id":"smaller","label":"Chest B","size":75}],"objectType":"chest"},{"prompt":"Choose the smaller chest.","answer":"smaller","full":"Chest B is smaller than Chest A.","hint":"Look for the chest that takes up less space.","explain":"Chest B is smaller than Chest A.","objects":[{"id":"bigger","label":"Chest A","size":143},{"id":"smaller","label":"Chest B","size":72}],"objectType":"chest"},{"prompt":"Choose the taller tower for the flag.","answer":"taller","full":"Tower A is taller than Tower B.","hint":"Compare the two towers. Which one is higher?","explain":"Tower A is taller than Tower B. Taller compares two heights.","objects":[{"id":"taller","label":"Tower A","size":150},{"id":"shorter","label":"Tower B","size":80}],"objectType":"tower"}]}],"rules":[["shop","Counting supplies","There is one ... · There are two ...","Use is for one. Use are for more than one. Some plural words change.","One child, two children. One mouse, two mice."],["bridge","Talking about friends","he · she · they · his · her","Use he for a boy, she for a girl, and they for two or more people. His and her show who owns something.","Mei is a girl. She has a ruler. It is her ruler."],["train","Daily routines","I play · She plays · They play","Use these words for routines. Always means every time.","He always packs his bag."],["boat","Actions now","am / is / are + an -ing word","Use am with I, is with he or she, and are with we or they.","We are drawing now."],["pickaxe","Actions in the past","play → played · go → went · eat → ate","Yesterday and last night tell us an action is in the past.","Yesterday, Amir went to the park."],["portal","Linking words","and = add · or = choose · but = show a difference","Choose a word that matches the ideas you want to join.","I like cats, but I do not like snakes."],["cat","Places","in · on · under · behind · between","Inside · on top · below · at the back · in the middle of two things.","The cat is between the rocks."],["castle","Comparing two things","tall → taller · big → bigger · small → smaller","Use taller or shorter for height. Use bigger or smaller for size.","Tower A is taller than Tower B."]],"curriculum":{"document":"KSSR (Semakan 2017), SK, CEFR-aligned","title":"DSKP Bahasa Inggeris SK Tahun 3 — Primary Year 3 English Language Syllabus","url":"https://bpk.moe.gov.my/kurikulum/kssr/kssr-tahun-3/102-001-dskp-kssr-semakan-2017-bi-sk-thn3-print/file","grammarPages":"Printed pages 43–45 (PDF pages 57–59); recycled Year 1–2 structures in Appendix 2","learningStandards":["3.2.2: Read details in short, simple texts.","4.2.4: Describe people and objects with suitable vocabulary.","4.2.5: Link sentences with basic coordinating conjunctions.","4.3.1: Practise capitals and sentence punctuation through guided word ordering.","4.3.3: Plan and form a range of simple sentences."],"note":"Original supported practice for pupils needing short, scaffolded tasks. Content selects Year 3 grammar and recycled Year 1–2 language: plurals, pronouns, present simple and continuous, simple past, conjunctions, position words and short-adjective comparisons. Hints, audio, small choices and retry feedback support learning. Game points do not determine a DSKP performance level."}},"y3-challenge":{"year":3,"levelLabel":"Challenge explorer","missions":[{"id":"y3-challenge-market","title":"Clue Market","topic":"Irregular plurals · there is / are · how many","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"subtitle":"Count the village supplies","guide":"Tap the correct word block. Help the market count its supplies!","taskLabel":"Shop supplied","reminder":"Children and mice are irregular plurals. Match is or are to the number of things. Use how many for things we count.","tasks":[{"prompt":"Two ___ are playing outside. One is a boy and one is a girl.","options":["child","children","childs"],"answer":"children","full":"Two children are playing outside.","hint":"Child has the irregular plural children.","explain":"Use children after two, not child or childs.","difficulty":"medium"},{"prompt":"Three ___ are near the cheese. Each one is a little mouse.","options":["mouse","mice","mouses"],"answer":"mice","full":"Three mice are near the cheese.","hint":"The plural of mouse is mice.","explain":"Mice is the irregular plural form used after three.","difficulty":"medium"},{"prompt":"One bag is on the chair. There ___ one bag on the chair.","options":["is","are","am"],"answer":"is","full":"There is one bag on the chair.","hint":"One bag is singular.","explain":"There is agrees with the singular noun bag.","difficulty":"medium"},{"prompt":"I put one box on the stall. My friend adds two boxes. There ___ three boxes now.","options":["is","are","am"],"answer":"are","full":"There are three boxes on the stall now.","hint":"One box and two boxes make more than one box.","explain":"Three boxes is plural, so the sentence uses are.","difficulty":"upper-medium"},{"prompt":"There are six children in the shop. How ___ children are there?","options":["much","many","any"],"answer":"many","full":"How many children are there?","hint":"Children are people we can count.","explain":"How many asks for the number of countable things or people.","difficulty":"upper-medium"}]},{"id":"y3-challenge-bridge","title":"Ownership Bridge","topic":"her · our · us · them · ownership clues","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"subtitle":"Help your friends cross","guide":"Tap the correct pronoun block. Build a bridge for your friends!","taskLabel":"Bridge block added","reminder":"Find who owns the item or who receives the action. Her and our come before nouns; us and them replace people after an action or preposition.","tasks":[{"prompt":"A girl called Mila owns the green bag. This is ___ bag.","options":["his","her","their"],"answer":"her","full":"This is her bag.","hint":"Use her before a noun belonging to the girl.","explain":"Her shows that the bag belongs to Mila.","difficulty":"medium"},{"prompt":"Adam and I share this room. This is ___ room.","options":["our","my","his"],"answer":"our","full":"This is our room.","hint":"Adam and I means we.","explain":"Our shows that the room belongs to both of us.","difficulty":"medium"},{"prompt":"Mum is calling Adam and me. She is calling ___.","options":["us","they","her"],"answer":"us","full":"She is calling us.","hint":"Adam and me includes the speaker. Use the object form us.","explain":"Us replaces Adam and me after calling.","difficulty":"upper-medium"},{"prompt":"These books belong to Lina and Mei. Please give the books to ___.","options":["them","it","we"],"answer":"them","full":"Please give the books to them.","hint":"Lina and Mei are two people. An object pronoun is needed after to.","explain":"Them replaces the two owners after the preposition to.","difficulty":"upper-medium"},{"prompt":"A boy has a blue cap and his sister has a red cap. The red cap is ___ cap.","options":["his","her","our"],"answer":"her","full":"The red cap is her cap.","hint":"Find the owner of the red cap, not the blue one.","explain":"The sister owns the red cap, so her is the correct possessive adjective.","difficulty":"upper-medium"}]},{"id":"y3-challenge-train","title":"Routine Train","topic":"always · sometimes · never · often · how often","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"subtitle":"Build a daily routine","guide":"Tap the word carriages in order. Build a routine to move the train!","taskLabel":"Train journey completed","reminder":"Always, sometimes, never and often usually come before the main verb. After do or does in these questions, use the base verb.","tasks":[{"prompt":"Describe her routine. Start with She; put always before walks.","words":["She","always","walks","to","school."],"answer":"She always walks to school.","full":"She always walks to school.","hint":"Use She always walks, then to school.","explain":"Always goes before walks; use walks after She.","scene":"boy","difficulty":"medium"},{"prompt":"Describe a routine. Start with We; put sometimes before play.","words":["We","sometimes","play","football","after","school."],"answer":"We sometimes play football after school.","full":"We sometimes play football after school.","hint":"Use We sometimes play, then football after school.","explain":"Sometimes tells us how often we play football.","scene":"boy","difficulty":"medium"},{"prompt":"Describe his routine. Start with He; put never before eats.","words":["He","never","eats","meat."],"answer":"He never eats meat.","full":"He never eats meat.","hint":"Use He never eats, then meat.","explain":"Never means at no time. Use eats with He.","scene":"boy","difficulty":"medium"},{"prompt":"Ask a routine question. Start with Do; put often before read.","words":["Do","you","often","read","at","night?"],"answer":"Do you often read at night?","full":"Do you often read at night?","hint":"Use Do you often read, then at night.","explain":"A present simple question uses Do you and the base verb read.","scene":"boy","difficulty":"upper-medium"},{"prompt":"Ask about her tennis routine. Start with How often.","words":["How","often","does","she","play","tennis?"],"answer":"How often does she play tennis?","full":"How often does she play tennis?","hint":"Use How often does she, then the base verb play.","explain":"Does she is followed by play, not plays. How often asks about frequency.","scene":"boy","difficulty":"upper-medium"}]},{"id":"y3-challenge-river","title":"Action River","topic":"Actions now · statements · negatives · questions","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"subtitle":"Build actions happening now","guide":"Put the word blocks in order. Build a boat with an action happening now!","taskLabel":"Boat launched","reminder":"Use am, is or are with an ing verb. Put not after the helping verb. In a question, the helping verb comes before the subject.","tasks":[{"prompt":"Describe what is happening now. Start with The.","words":["The","boys","are","swimming."],"answer":"The boys are swimming.","full":"The boys are swimming.","hint":"The boys is plural. Use are before swimming.","explain":"Are swimming describes what the boys are doing now.","scene":"boy","difficulty":"medium"},{"prompt":"Describe the girl now. Start with My.","words":["My","sister","is","drawing","a","cat."],"answer":"My sister is drawing a cat.","full":"My sister is drawing a cat.","hint":"Use My sister is, then drawing a cat.","explain":"My sister is one person, so use is drawing.","scene":"boy","difficulty":"medium"},{"prompt":"Say that they are not playing now. Start with They; finish with now.","words":["They","are","not","playing","football","now."],"answer":"They are not playing football now.","full":"They are not playing football now.","hint":"Put not between are and playing.","explain":"The negative present continuous uses are not plus an ing verb.","scene":"boy","difficulty":"upper-medium"},{"prompt":"Ask about your brother now. Start with Is.","words":["Is","your","brother","reading","a","book?"],"answer":"Is your brother reading a book?","full":"Is your brother reading a book?","hint":"Use Is your brother, then reading a book.","explain":"Move is before the subject to form a present continuous question.","scene":"boy","difficulty":"upper-medium"},{"prompt":"Ask about the children now. Start with What; finish with now.","words":["What","are","the","children","doing","now?"],"answer":"What are the children doing now?","full":"What are the children doing now?","hint":"Use What are the children, then doing now.","explain":"Use are with children; What asks about the action.","scene":"boy","difficulty":"upper-medium"}]},{"id":"y3-challenge-mine","title":"Story Mine","topic":"Past stories · went · found · were · broke · put","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"subtitle":"Find words from the past","guide":"Tap the correct word block. Find a gem for each action from yesterday!","taskLabel":"Past gem found","reminder":"Keep completed story events in the past. Some past forms change, such as go to went. Put stays put in the past.","tasks":[{"prompt":"Yesterday, our class ___ to the zoo by bus.","options":["go","went","goes"],"answer":"went","full":"Yesterday, our class went to the zoo by bus.","hint":"Yesterday needs the past form of go.","explain":"Went is the irregular past form of go.","difficulty":"medium"},{"prompt":"Yesterday, Aina ___ a small shell on the beach.","options":["find","found","finding"],"answer":"found","full":"Yesterday, Aina found a small shell on the beach.","hint":"Find changes to found in the past.","explain":"Found describes the completed action yesterday.","difficulty":"medium"},{"prompt":"The children ___ at school yesterday, but today they are at home.","options":["was","were","is"],"answer":"were","full":"The children were at school yesterday.","hint":"Children is plural, and yesterday is in the past.","explain":"Use were for a plural subject in the past.","difficulty":"medium"},{"prompt":"Ben dropped his glass. It ___ on the floor.","options":["breaks","broke","breaking"],"answer":"broke","full":"It broke on the floor.","hint":"Dropped begins a past event. Continue with a past verb.","explain":"Broke continues the story in the past; breaks is present and breaking needs a helping verb.","difficulty":"upper-medium"},{"prompt":"Ben drank some water. Then he ___ the empty cup on the table.","options":["puts","put","putting"],"answer":"put","full":"Then he put the empty cup on the table.","hint":"Drank and then show a sequence of completed past actions.","explain":"The past form of put stays put. He puts would describe a present routine.","difficulty":"upper-medium"}]},{"id":"y3-challenge-portal","title":"Choice Portal","topic":"and · or · but · match meaning to clues","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"subtitle":"Join the story blocks","guide":"Read the story clue. Tap a linking word to open the portal!","taskLabel":"Story portal opened","reminder":"And adds. Or gives a choice. But joins different or opposite ideas.","tasks":[{"prompt":"Would you like milk ___ juice? Please choose one drink.","options":["and","or","but"],"answer":"or","full":"Would you like milk or juice?","hint":"Or gives a choice between two things.","explain":"The speaker asks the listener to choose one drink, so use or.","difficulty":"medium"},{"prompt":"Mia has a ruler ___ a pencil. She has both things.","options":["or","but","and"],"answer":"and","full":"Mia has a ruler and a pencil.","hint":"Both things are included.","explain":"And adds one item to another.","difficulty":"medium"},{"prompt":"Ben has a new bike, ___ he cannot ride it yet.","options":["and","or","but"],"answer":"but","full":"Ben has a new bike, but he cannot ride it yet.","hint":"Having a bike and being unable to ride it are contrasting ideas.","explain":"But joins the unexpected contrast between owning a bike and being unable to ride it.","difficulty":"upper-medium"},{"prompt":"There is one snack for you. Take an apple ___ a banana; do not take both.","options":["and","but","or"],"answer":"or","full":"Take an apple or a banana.","hint":"The instruction allows only one of the two snacks.","explain":"Or matches a choice of one snack rather than both.","difficulty":"upper-medium"},{"prompt":"The bag looks small, ___ it can hold many books.","options":["or","and","but"],"answer":"but","full":"The bag looks small, but it can hold many books.","hint":"Holding many books is unexpected for a small-looking bag.","explain":"But connects the contrast between the appearance and what the bag can hold.","difficulty":"upper-medium"}]},{"id":"y3-challenge-rescue","title":"Hideout Rescue","topic":"in · on · under · behind · between","type":"place","color":"#ff9c95","icon":"cat","x":42,"y":22,"subtitle":"Give the cat a safe place","guide":"Tap the cat, then tap its place. You can also drag the cat!","taskLabel":"Cat rescued","reminder":"Read the place word. In is inside. Behind is at the back. Between is in the middle.","tasks":[{"prompt":"Put the cat in the box, not on the table.","answer":"in","full":"The cat is in the box.","hint":"Choose the inside of the box.","explain":"In describes a position inside the box.","difficulty":"medium"},{"prompt":"The cat is below the table top. Put it under the table.","answer":"under","full":"The cat is under the table.","hint":"Choose the space beneath the table.","explain":"Under means below the table, not on top of it.","difficulty":"medium"},{"prompt":"Keep the cat off the floor. Put it on the table top.","answer":"on","full":"The cat is on the table.","hint":"Choose the top surface of the table.","explain":"On describes the cat resting on the table top.","difficulty":"medium"},{"prompt":"The cat is outdoors. It is not at the table or in the box. Hide it behind the tree.","answer":"behind","full":"The cat is behind the tree.","hint":"Choose the hiding place at the back of the tree.","explain":"Behind places the cat at the back of the tree rather than at the table or in the box.","difficulty":"upper-medium"},{"prompt":"The cat needs a place outside the box and away from the table. Put it between the two rocks.","answer":"between","full":"The cat is between the rocks.","hint":"Find the middle space with a rock on each side.","explain":"Between describes the middle position with one rock on each side.","difficulty":"upper-medium"}]},{"id":"y3-challenge-castle","title":"Clue Castle","topic":"Comparisons · one clue · two clues","type":"compare","color":"#e5b3f0","icon":"castle","x":89,"y":73,"subtitle":"Compare two objects","guide":"Look at both objects. Tap the one that matches the words!","taskLabel":"Castle light switched on","reminder":"Taller and shorter compare heights. Bigger and smaller compare sizes.","tasks":[{"prompt":"Tap the tower that is taller than the other tower.","objects":[{"id":"a","label":"Tower A","size":80},{"id":"b","label":"Tower B","size":150}],"objectType":"tower","answer":"b","full":"Tower B is taller than Tower A.","hint":"Compare the heights. Choose the tower that reaches higher.","explain":"Taller compares the heights of the two towers.","difficulty":"medium"},{"prompt":"Choose the tower that is smaller than the other tower.","objects":[{"id":"a","label":"Tower A","size":145},{"id":"b","label":"Tower B","size":80}],"objectType":"tower","answer":"b","full":"Tower B is smaller than Tower A.","hint":"Compare the overall sizes of the two towers.","explain":"Smaller compares the sizes of two objects.","difficulty":"medium"},{"prompt":"Tap the tower that is taller than Tower A but shorter than Tower C.","objects":[{"id":"a","label":"Tower A","size":70},{"id":"b","label":"Tower B","size":110},{"id":"c","label":"Tower C","size":155}],"objectType":"tower","answer":"b","full":"Tower B is taller than Tower A but shorter than Tower C.","hint":"Find one tower that fits both comparisons.","explain":"Tower B is above A in height and below C, so both parts are true.","difficulty":"upper-medium"},{"prompt":"Choose a tower that is shorter than Tower A but taller than Tower B.","objects":[{"id":"a","label":"Tower A","size":150},{"id":"b","label":"Tower B","size":70},{"id":"c","label":"Tower C","size":110}],"objectType":"tower","answer":"c","full":"Tower C is shorter than Tower A but taller than Tower B.","hint":"Do not choose A or B. Compare the remaining tower with each one.","explain":"Tower C fits both comparisons: it is lower than A and higher than B.","difficulty":"upper-medium"},{"prompt":"The tower you need is bigger than Tower C and smaller than Tower B. Which tower fits both clues?","objects":[{"id":"a","label":"Tower A","size":110},{"id":"b","label":"Tower B","size":155},{"id":"c","label":"Tower C","size":70}],"objectType":"tower","answer":"a","full":"Tower A is bigger than Tower C and smaller than Tower B.","hint":"Check both size clues before choosing.","explain":"Tower A is larger than C and smaller than B; the other towers fail one of the clues.","difficulty":"upper-medium"}]}],"rules":[["shop","Count the clues","one child → two children · one mouse → three mice","Use there is with one thing and there are with more than one. Ask how many for a number.","There are three boxes. How many children are there?"],["bridge","Owners and objects","her bag · our room · calling us · give to them","Find the owner first. Use an object pronoun after an action or a preposition.","Mum is calling Adam and me. She is calling us."],["train","How often?","always · sometimes · never · often","These frequency words go before the main verb in our sentences. Use a base verb after do or does.","She always walks to school. How often does she play tennis?"],["boat","Actions now","They are swimming. · They are not playing. · Is he reading?","Use am, is or are with an ing verb. Change the word order to ask a question.","What are the children doing now?"],["pickaxe","Past story clues","go → went · find → found · break → broke · put → put","Yesterday, completed events and then can show a past story. Keep the verb in the past.","Ben drank some water. Then he put the cup on the table."],["portal","Choose the link","and = both · or = choose · but = contrast","Read both ideas before choosing the joining word.","The bag looks small, but it can hold many books."],["cat","Find the place","in · on · under · behind · between","Read all the position clues, then choose the matching place.","The cat is between the two rocks."],["castle","Use both clues","taller than A · shorter than C","One tower must fit both comparisons. Check the first clue and then the second.","Tower B is taller than Tower A but shorter than Tower C."]],"curriculum":{"document":"KSSR (Semakan 2017), SK, CEFR-aligned","title":"DSKP Bahasa Inggeris SK Tahun 3 — Primary Year 3 English Language Syllabus","url":"https://bpk.moe.gov.my/kurikulum/kssr/kssr-tahun-3/102-001-dskp-kssr-semakan-2017-bi-sk-thn3-print/file","grammarPages":"Printed pages 43–45 (PDF pages 57–59); recycled Year 1–2 structures in Appendix 2","learningStandards":["3.2.2: Read details in short, simple texts.","4.2.4: Describe people and objects with suitable vocabulary.","4.2.5: Link sentences with basic coordinating conjunctions.","4.3.1: Practise capitals and sentence punctuation through guided word ordering.","4.3.3: Plan and form a range of simple sentences."],"note":"Original 3K practice: exactly 20 medium and 20 upper-medium activities within Year 3 SK language. Medium items apply a grammar pattern to a short familiar context. Upper-medium items add connected clues, pronoun reference, question word order, contrast or two comparisons; they do not introduce a higher-year grammar syllabus. Selected Year 3 grammar: irregular plurals, subject/object/possessive pronouns, frequency adverbs, conjunctions, past simple, prepositions and short-adjective comparisons. Present simple and continuous recycle Year 2 language as permitted. Difficulty labels are design categories, not PBD or CEFR levels.","mirrorUrl":"https://anyflip.com/pzxi/hnnp/basic/51-77","reviewedAt":"2026-10-18"},"difficultyDistribution":{"medium":20,"upper-medium":20}},"y4-foundation":{"year":4,"levelLabel":"Foundation explorer","missions":[{"id":"y4-foundation-market","title":"Picnic Market","topic":"much · many · some · any · there is / are","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"subtitle":"Pack food for the picnic","guide":"Read the food clue. Tap a word block to pack the picnic basket!","taskLabel":"Picnic food packed","reminder":"Count carrots: many carrots. Milk is an amount: much milk. Use some in these positive sentences and any after isn't.","tasks":[{"prompt":"How ___ apples are there? We can count apples.","options":["many","much"],"answer":"many","full":"How many apples are there?","hint":"Apples can be counted. Use many.","explain":"Use many with countable plural nouns such as apples.","difficulty":"low"},{"prompt":"How ___ water is in the bottle?","options":["many","much"],"answer":"much","full":"How much water is in the bottle?","hint":"Water is an amount, not separate items.","explain":"Use much when asking about an amount of water.","difficulty":"low"},{"prompt":"We have oranges. There are ___ oranges in the bag.","options":["some","any"],"answer":"some","full":"There are some oranges in the bag.","hint":"This positive sentence says we have oranges.","explain":"Some gives a positive amount without an exact number.","difficulty":"low"},{"prompt":"The glass is empty. There is not ___ milk in it.","options":["some","any"],"answer":"any","full":"There is not any milk in it.","hint":"Not makes this sentence negative.","explain":"Use any after not to say there is no milk.","difficulty":"lower-medium"},{"prompt":"Two bananas are on the table. There ___ two bananas.","options":["is","are"],"answer":"are","full":"There are two bananas on the table.","hint":"Two bananas means more than one.","explain":"There are goes with a plural noun such as bananas.","difficulty":"lower-medium"}]},{"id":"y4-foundation-bridge","title":"My Things Bridge","topic":"my · her · his · mine · 's","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"subtitle":"Return the lost belongings","guide":"Read who owns each thing. Tap the right block to return it!","taskLabel":"Belonging returned","reminder":"Use my or her before a noun. Mine and his can show ownership without repeating the noun.","tasks":[{"prompt":"I own this bag. It is ___ bag.","options":["my","her"],"answer":"my","full":"It is my bag.","hint":"The speaker says I own it.","explain":"My shows that something belongs to the speaker.","difficulty":"low"},{"prompt":"A girl has a red hat. This is ___ hat.","options":["his","her"],"answer":"her","full":"This is her hat.","hint":"Use her for something belonging to the girl.","explain":"Her is a possessive adjective used before hat.","difficulty":"low"},{"prompt":"A boy owns this kite. The kite is ___.","options":["his","hers"],"answer":"his","full":"The kite is his.","hint":"A boy owns the kite. Choose his.","explain":"His can stand alone to show that the kite belongs to the boy.","difficulty":"lower-medium"},{"prompt":"I own the blue book. The blue book is ___.","options":["mine","yours"],"answer":"mine","full":"The blue book is mine.","hint":"The speaker owns the book. Use mine without another noun.","explain":"Mine means the book belongs to me.","difficulty":"lower-medium"},{"prompt":"The bag belongs to Ali. It is ___ bag.","options":["Ali","Ali's"],"answer":"Ali's","full":"It is Ali's bag.","hint":"Add apostrophe s to Ali to show ownership.","explain":"Ali's shows that the bag belongs to Ali.","difficulty":"lower-medium"}]},{"id":"y4-foundation-train","title":"Daily Train","topic":"Simple routines · actions now","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"subtitle":"Spot a routine or an action now","guide":"Read the time clue. Put the word carriages in order to move the train!","taskLabel":"Time clue solved","reminder":"Every day tells us about a routine. Now tells us an action is happening: am, is or are + an -ing word.","tasks":[{"prompt":"Build a routine sentence. Start with I.","words":["I","walk","to","school."],"answer":"I walk to school.","full":"I walk to school.","hint":"Start I walk. Put to school at the end.","explain":"I walk describes a routine in the present simple.","scene":"boy","difficulty":"low"},{"prompt":"Describe what she is doing now. Start with She.","words":["She","is","reading","now."],"answer":"She is reading now.","full":"She is reading now.","hint":"Use She is, then reading, then now.","explain":"She is reading describes an action happening now.","scene":"boy","difficulty":"low"},{"prompt":"Describe the boys now. Start with They.","words":["They","are","eating","lunch."],"answer":"They are eating lunch.","full":"They are eating lunch.","hint":"Use They are before eating.","explain":"Use are with They in the present continuous.","scene":"boy","difficulty":"low"},{"prompt":"Describe a daily routine. Start with We; finish with every day.","words":["We","drink","water","every","day."],"answer":"We drink water every day.","full":"We drink water every day.","hint":"Put We drink water before every day.","explain":"Every day shows a routine, so use drink with We.","scene":"boy","difficulty":"lower-medium"},{"prompt":"Describe Ali on Sundays. Start with Ali; finish with on Sundays.","words":["Ali","plays","football","on","Sundays."],"answer":"Ali plays football on Sundays.","full":"Ali plays football on Sundays.","hint":"Use Ali plays football, then on Sundays.","explain":"A singular subject such as Ali takes plays for a present simple routine.","scene":"boy","difficulty":"lower-medium"}]},{"id":"y4-foundation-river","title":"Wish River","topic":"like / enjoy / love + ing · want + to","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"subtitle":"Tell us what you enjoy or want","guide":"Put the word blocks in order. Build a wish or a favourite activity!","taskLabel":"Wish boat launched","reminder":"Enjoy goes with an -ing word: enjoy playing. Want goes with to + a verb: want to play. Love can also go with an -ing word.","tasks":[{"prompt":"Say what you like. Start with I.","words":["I","like","reading","books."],"answer":"I like reading books.","full":"I like reading books.","hint":"Put reading after like.","explain":"Like can be followed by an ing form such as reading.","scene":"boy","difficulty":"low"},{"prompt":"Say what you want. Start with We.","words":["We","want","to","swim."],"answer":"We want to swim.","full":"We want to swim.","hint":"Put to before swim.","explain":"Use want to followed by the base form swim.","scene":"boy","difficulty":"low"},{"prompt":"Say what she enjoys. Start with She.","words":["She","enjoys","playing","games."],"answer":"She enjoys playing games.","full":"She enjoys playing games.","hint":"Put playing after enjoys.","explain":"Enjoys is followed by an ing form, so use playing.","scene":"boy","difficulty":"lower-medium"},{"prompt":"Say what they love. Start with They.","words":["They","love","drawing","cats."],"answer":"They love drawing cats.","full":"They love drawing cats.","hint":"Use drawing after love.","explain":"Love can be followed by an ing form such as drawing.","scene":"boy","difficulty":"lower-medium"},{"prompt":"Say what he wants. Start with He.","words":["He","wants","to","eat."],"answer":"He wants to eat.","full":"He wants to eat.","hint":"Use He wants, then to eat.","explain":"Use wants with He, followed by to and the base verb eat.","scene":"boy","difficulty":"lower-medium"}]},{"id":"y4-foundation-mine","title":"Memory Mine","topic":"Past actions · helped · went · saw · could","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"subtitle":"Find memories and past skills","guide":"Read the past clue. Mine the word block that completes the memory!","taskLabel":"Memory gem found","reminder":"Yesterday and last night are in the past. Help becomes helped, go becomes went, and see becomes saw. Could describes a past ability.","tasks":[{"prompt":"Yesterday, I ___ Mum in the kitchen.","options":["help","helped"],"answer":"helped","full":"Yesterday, I helped Mum in the kitchen.","hint":"Yesterday tells us the action is in the past.","explain":"Helped is the past form of help.","difficulty":"low"},{"prompt":"Last night, we ___ a film.","options":["watched","watch"],"answer":"watched","full":"Last night, we watched a film.","hint":"Use the past form ending in ed.","explain":"Watched is the regular past form of watch.","difficulty":"low"},{"prompt":"Yesterday, they ___ their grandmother.","options":["visit","visited"],"answer":"visited","full":"Yesterday, they visited their grandmother.","hint":"Add ed to visit for this past action.","explain":"Visited is the past form of visit.","difficulty":"low"},{"prompt":"We go to the park on Sundays. Yesterday, we ___ to the zoo.","options":["go","went"],"answer":"went","full":"Yesterday, we went to the zoo.","hint":"Go changes to went in the past.","explain":"Went is the irregular past form of go.","difficulty":"lower-medium"},{"prompt":"I can swim now. When I was five, I ___ swim too.","options":["can","could"],"answer":"could","full":"When I was five, I could swim too.","hint":"When I was five refers to ability in the past.","explain":"Could is the past form of can and shows past ability.","difficulty":"lower-medium"}]},{"id":"y4-foundation-portal","title":"Tomorrow Portal","topic":"am / is / are going to · future plans","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"subtitle":"Make a plan for tomorrow","guide":"Read each plan. Tap the correct block to open tomorrow's portal!","taskLabel":"Plan portal opened","reminder":"For a plan, use am, is or are + going to + a verb. I am going to plant. She is going to plant. We are going to plant.","tasks":[{"prompt":"Tomorrow, I ___ going to draw a cat.","options":["am","are"],"answer":"am","full":"Tomorrow, I am going to draw a cat.","hint":"Use am with I.","explain":"I am going to describes a future plan.","difficulty":"low"},{"prompt":"Tomorrow, she ___ going to visit her aunt.","options":["is","are"],"answer":"is","full":"Tomorrow, she is going to visit her aunt.","hint":"Use is with she.","explain":"She is going to describes her future plan.","difficulty":"low"},{"prompt":"We have a plan for Saturday. We ___ going to play football.","options":["is","are"],"answer":"are","full":"We are going to play football.","hint":"Use are with we.","explain":"Use We are going to for a shared future plan.","difficulty":"lower-medium"},{"prompt":"Ali has a ticket for tomorrow. He is going ___ travel by bus.","options":["to","at"],"answer":"to","full":"He is going to travel by bus.","hint":"The pattern is going to plus a base verb.","explain":"Use going to travel, not going at travel.","difficulty":"lower-medium"},{"prompt":"They have a picnic plan. They are going to ___ sandwiches.","options":["make","making","made"],"answer":"make","full":"They are going to make sandwiches.","hint":"After going to, use the base form of the verb.","explain":"Make is the base verb used after going to.","difficulty":"lower-medium"}]},{"id":"y4-foundation-rescue","title":"Reason Rescue","topic":"Why? · because · give a reason","type":"rune","color":"#ff9c95","icon":"cat","x":42,"y":22,"subtitle":"Explain how to help the cat","guide":"Read the cat's clue. Choose a reason to help the rescue team!","taskLabel":"Rescue reason explained","reminder":"Why asks for a reason. Because introduces a reason: We help the cat because it is cold.","tasks":[{"prompt":"I drink water ___ I am thirsty.","options":["because","or"],"answer":"because","full":"I drink water because I am thirsty.","hint":"Being thirsty is the reason for drinking water.","explain":"Because links the action to its reason.","difficulty":"low"},{"prompt":"She wears a coat ___ it is cold.","options":["and","because"],"answer":"because","full":"She wears a coat because it is cold.","hint":"The cold weather is the reason.","explain":"Use because to give the reason for wearing a coat.","difficulty":"low"},{"prompt":"Why are you eating? I am eating ___ I am hungry.","options":["because","but"],"answer":"because","full":"I am eating because I am hungry.","hint":"A Why question asks for a reason.","explain":"Because I am hungry answers the Why question.","difficulty":"low"},{"prompt":"It is raining. Why is Ali using an umbrella?","options":["Because it is raining.","Because it is sunny."],"answer":"Because it is raining.","full":"Ali is using an umbrella because it is raining.","hint":"Choose the reason that matches the rain.","explain":"The rain explains why Ali is using an umbrella.","difficulty":"lower-medium"},{"prompt":"Mia wants to read. The room is dark. Why does she turn on the light?","options":["Because she needs to see the book.","Because the book is wet."],"answer":"Because she needs to see the book.","full":"Mia turns on the light because she needs to see the book.","hint":"A light helps Mia see in a dark room.","explain":"The reason connects the dark room with reading the book.","difficulty":"lower-medium"}]},{"id":"y4-foundation-castle","title":"Tower Castle","topic":"taller than · shorter than · bigger than · smaller than","type":"compare","color":"#e5b3f0","icon":"castle","x":89,"y":73,"subtitle":"Compare the castle objects","guide":"Look at the labels and sizes. Tap the object that matches the comparison!","taskLabel":"Castle comparison solved","reminder":"Taller and shorter compare heights. Bigger and smaller compare sizes. Than tells us which other object to compare with.","tasks":[{"prompt":"Tap the taller tower.","objects":[{"id":"a","label":"Tower A","size":80},{"id":"b","label":"Tower B","size":150}],"objectType":"tower","answer":"b","full":"Tower B is taller than Tower A.","hint":"Look for the tower that reaches higher.","explain":"Tower B reaches higher, so it is taller.","difficulty":"low"},{"prompt":"Tap the shorter tower.","objects":[{"id":"a","label":"Tower A","size":140},{"id":"b","label":"Tower B","size":75}],"objectType":"tower","answer":"b","full":"Tower B is shorter than Tower A.","hint":"The shorter tower does not reach as high.","explain":"Tower B is lower than Tower A, so it is shorter.","difficulty":"low"},{"prompt":"Tower A is on the left. Tap the tower that is taller than Tower A.","objects":[{"id":"a","label":"Tower A","size":85},{"id":"b","label":"Tower B","size":145}],"objectType":"tower","answer":"b","full":"Tower B is taller than Tower A.","hint":"Compare the two heights. Tower B reaches higher.","explain":"Taller than compares the heights of two towers.","difficulty":"lower-medium"},{"prompt":"Tower B is on the right. Tap the tower that is shorter than Tower B.","objects":[{"id":"a","label":"Tower A","size":90},{"id":"b","label":"Tower B","size":150}],"objectType":"tower","answer":"a","full":"Tower A is shorter than Tower B.","hint":"Look for a tower lower than Tower B.","explain":"Tower A is shorter because it does not reach as high as Tower B.","difficulty":"lower-medium"},{"prompt":"Look at both towers. Tap the bigger tower.","objects":[{"id":"a","label":"Tower A","size":150},{"id":"b","label":"Tower B","size":85}],"objectType":"tower","answer":"a","full":"Tower A is bigger than Tower B.","hint":"The bigger tower is shown at a larger size.","explain":"Bigger than compares the sizes of the two towers.","difficulty":"lower-medium"}]}],"rules":[["shop","Food and amounts","many apples · much water · some oranges · not any milk","Use many for countable things and much for an amount. Use some in these positive sentences and any after not.","How many apples are there? There is not any milk."],["bridge","Whose things?","my bag · her hat · the kite is his · the book is mine","My and her come before nouns. Mine and his can stand alone. Add apostrophe s to a name to show ownership.","It is Ali's bag. The blue book is mine."],["train","Routines and now","I walk · Ali plays · she is reading · they are eating","Use the present simple for routines. Use am, is or are with an ing verb for an action now.","We drink water every day. She is reading now."],["boat","Likes and wishes","like reading · enjoys playing · want to swim","Use an ing form after enjoy. After want or wants, use to and a base verb.","She enjoys playing games. He wants to eat."],["pickaxe","Past actions and ability","helped · watched · visited · went · could","Yesterday and last night refer to the past. Could shows ability in the past.","Yesterday, we went to the zoo. I could swim when I was five."],["portal","Future plans","I am going to · she is going to · we are going to","Use am, is or are going to, then a base verb.","We are going to make sandwiches."],["cat","Give a reason","Why? · because","Because tells us the reason for an action. Match the reason to the situation.","She wears a coat because it is cold."],["castle","Compare towers","taller than · shorter than · bigger than","Compare the height or size of the two objects.","Tower B is taller than Tower A."]],"curriculum":{"document":"KSSR (Semakan 2017) Standards-Based English Language Curriculum, Sekolah Kebangsaan, Year 4; Bahagian Pembangunan Kurikulum, Ministry of Education Malaysia, April 2018","title":"English Language Year 4 (SK) DSKP — Primary Year 4 Syllabus","url":"https://bpk.moe.gov.my/kurikulum/kssr/kssr-tahun-3-1/138-003-dskp-kssr-semakan-2017-bi-sk-thn4-print/file","grammarPages":"Printed syllabus pages 45–47 (PDF pages 59–61); earlier grammar in Appendix 1, printed pages 53–54 (PDF pages 67–68). Relevant learning standards: printed pages 26, 31 and 35–36 (PDF pages 40, 45 and 49–50).","learningStandards":["4.2.1: Language for giving reasons for simple opinions, supported here by because sentences.","4.2.3: Language for describing basic daily routines, supported here by guided sentence ordering.","4.2.4: Suitable language for describing people and objects, supported here by ownership and comparison statements.","4.3.1: Capital letters and sentence punctuation, practised here in guided word ordering; the full standard concerns writing at discourse level.","2.1.2: Language for describing past experiences; classroom speaking practice is needed to assess the full standard.","3.2.2: Reading for specific details is supported by short clues; the full standard expects simple texts of one or two paragraphs."],"note":"Original 4B foundation practice: exactly 20 low and 20 lower-medium activities. Short direct prompts, mostly two-choice blocks and short word banks reduce reading load; the second level adds a small context or grammar choice. Selected Year 4 grammar includes quantity, possession, verb patterns, past actions and could, going to, because and comparisons; present simple and continuous are explicitly recycled in the Year 4 syllabus. Difficulty labels are teacher-facing design categories, not PBD or CEFR performance judgements.","mirrorUrl":"https://fliphtml5.com/juojb/vqkc/DSKP_KSSR_Semakan_2017_Bahasa_Inggeris_Tahun_4/60/","reviewedAt":"2026-10-18"},"difficultyDistribution":{"low":20,"lower-medium":20}},"y4-supported":{"year":4,"levelLabel":"Step by step","missions":[{"id":"y4-market","title":"Picnic Market","topic":"much · many · some · any · there is / are","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"subtitle":"Pack food for the picnic","guide":"Read the food clue. Tap a word block to pack the picnic basket!","taskLabel":"Picnic food packed","reminder":"Count carrots: many carrots. Milk is an amount: much milk. Use some in these positive sentences and any after isn't.","tasks":[{"prompt":"We can count the carrots. How ___ carrots are in the basket?","options":["much","many"],"answer":"many","full":"How many carrots are in the basket?","hint":"One carrot, two carrots. We can count them. Use many.","explain":"Use many with carrots because carrots can be counted.","scene":"apple"},{"prompt":"Milk is a liquid. How ___ milk is in the bottle?","options":["much","many"],"answer":"much","full":"How much milk is in the bottle?","hint":"Milk is an amount. Use much with milk.","explain":"Use much to ask about an amount of milk.","scene":"apple"},{"prompt":"The basket has oranges. There are ___ oranges in the basket.","options":["any","some"],"answer":"some","full":"There are some oranges in the basket.","hint":"This sentence says we have oranges. Use some.","explain":"Some tells us there are oranges without giving an exact number.","scene":"apple"},{"prompt":"The cup is empty. There isn't ___ juice in the cup.","options":["some","any"],"answer":"any","full":"There isn't any juice in the cup.","hint":"Isn't makes this sentence negative. Use any.","explain":"There isn't any juice means there is no juice in the cup.","scene":"apple"},{"prompt":"Some bread is on the stall. There ___ some bread on the stall.","options":["is","are"],"answer":"is","full":"There is some bread on the stall.","hint":"Bread is an amount of food. Use There is some bread.","explain":"Use is with an uncountable amount such as some bread.","scene":"apple"}]},{"id":"y4-bridge","title":"Belongings Bridge","topic":"hers · mine · yours · whose · 's","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"subtitle":"Return the lost belongings","guide":"Read who owns each thing. Tap the right block to return it!","taskLabel":"Belonging returned","reminder":"Mine, yours and hers can stand alone. Whose asks who owns something. Ali's means belonging to Ali.","tasks":[{"prompt":"Aina is a girl. She owns this hat. The hat is ___.","options":["hers","her"],"answer":"hers","full":"The hat is hers.","hint":"Her goes before a thing: her hat. Hers can finish this sentence.","explain":"The hat is hers means the hat belongs to Aina.","scene":"girl"},{"prompt":"I own this red bag. The bag is ___.","options":["my","mine"],"answer":"mine","full":"The bag is mine.","hint":"My goes before bag. Mine can stand alone: The bag is mine.","explain":"Mine means belonging to me.","scene":"boy"},{"prompt":"This map belongs to you. The map is ___.","options":["yours","your"],"answer":"yours","full":"The map is yours.","hint":"Your goes before map. Yours can finish this sentence.","explain":"Yours means belonging to you.","scene":"friends"},{"prompt":"Ask who owns the bike: '___ bike is this?' 'It is Ali's bike.'","options":["Why","Whose"],"answer":"Whose","full":"Whose bike is this? It is Ali's bike.","hint":"Whose asks who owns a thing. Use Whose bike is this?","explain":"Whose asks about the owner. Ali's tells us that Ali owns the bike.","scene":"boy"},{"prompt":"The toy belongs to one cat. It is the ___ toy.","options":["cats'","cat's"],"answer":"cat's","full":"It is the cat's toy.","hint":"There is one cat. Add 's to cat: the cat's toy.","explain":"Cat's means belonging to one cat. Cats' would mean belonging to more than one cat.","scene":"friends"}]},{"id":"y4-train","title":"Time Clue Train","topic":"Every day · now · present simple / continuous","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"subtitle":"Spot a routine or an action now","guide":"Read the time clue. Put the word carriages in order to move the train!","taskLabel":"Time clue solved","reminder":"Every day tells us about a routine. Now tells us an action is happening: am, is or are + an -ing word.","tasks":[{"prompt":"Tell your daily routine. Start with I and finish with every day.","words":["I","feed","the","cat","every","day."],"answer":"I feed the cat every day.","full":"I feed the cat every day.","hint":"Start I feed the cat. Finish every day.","explain":"Feed describes a routine. Every day tells us how often it happens.","scene":"boy"},{"prompt":"The cat is sleeping at this moment. Start with The and finish with now.","words":["The","cat","is","sleeping","now."],"answer":"The cat is sleeping now.","full":"The cat is sleeping now.","hint":"Start The cat is. Add sleeping now.","explain":"Is sleeping describes an action happening now.","scene":"friends"},{"prompt":"Hana does this every morning. Start with Hana and finish with flowers.","words":["Hana","waters","the","flowers."],"answer":"Hana waters the flowers.","full":"Hana waters the flowers.","hint":"Start Hana waters. Add the flowers.","explain":"This is Hana's routine. Use waters with one person such as Hana.","scene":"girl"},{"prompt":"Two children are running at this moment. Start with They and finish with now.","words":["They","are","running","now."],"answer":"They are running now.","full":"They are running now.","hint":"Start They are. Add running now.","explain":"Use are with they. Are running describes an action happening now.","scene":"friends"},{"prompt":"You are carrying a bag at this moment. Tell us the action. Start with I.","words":["I","am","carrying","a","bag."],"answer":"I am carrying a bag.","full":"I am carrying a bag.","hint":"Start I am. Add carrying a bag.","explain":"Use am with I. Am carrying describes your action now.","scene":"boy"}]},{"id":"y4-river","title":"Wish River","topic":"enjoy / love + ing · want + to","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"subtitle":"Tell us what you enjoy or want","guide":"Put the word blocks in order. Build a wish or a favourite activity!","taskLabel":"Wish boat launched","reminder":"Enjoy goes with an -ing word: enjoy playing. Want goes with to + a verb: want to play. Love can also go with an -ing word.","tasks":[{"prompt":"You enjoy games. Build the sentence. Start with I and finish with games.","words":["I","enjoy","playing","games."],"answer":"I enjoy playing games.","full":"I enjoy playing games.","hint":"Start I enjoy. Add playing games.","explain":"Use playing after enjoy: I enjoy playing games.","scene":"boy"},{"prompt":"Aina wants a drink. Start with Aina and finish with water.","words":["Aina","wants","to","drink","water."],"answer":"Aina wants to drink water.","full":"Aina wants to drink water.","hint":"Start Aina wants. Add to drink water.","explain":"Use to drink after wants. Aina wants to drink water.","scene":"girl"},{"prompt":"You love making pictures. Start with I and finish with pictures.","words":["I","love","drawing","pictures."],"answer":"I love drawing pictures.","full":"I love drawing pictures.","hint":"Start I love. Add drawing pictures.","explain":"Love can go with an -ing activity: I love drawing pictures.","scene":"boy"},{"prompt":"You and your friends want to help the cat. Start with We and finish with cat.","words":["We","want","to","help","the","cat."],"answer":"We want to help the cat.","full":"We want to help the cat.","hint":"Start We want to help. Add the cat.","explain":"Use to help after want. We want to help the cat.","scene":"friends"},{"prompt":"Zaki enjoys books. Start with Zaki and finish with books.","words":["Zaki","enjoys","reading","books."],"answer":"Zaki enjoys reading books.","full":"Zaki enjoys reading books.","hint":"Start Zaki enjoys. Add reading books.","explain":"Use reading after enjoys: Zaki enjoys reading books.","scene":"boy"}]},{"id":"y4-mine","title":"Memory Mine","topic":"Past actions · helped · went · saw · could","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"subtitle":"Find memories and past skills","guide":"Read the past clue. Mine the word block that completes the memory!","taskLabel":"Memory gem found","reminder":"Yesterday and last night are in the past. Help becomes helped, go becomes went, and see becomes saw. Could describes a past ability.","tasks":[{"prompt":"Yesterday, Sara ___ her mum in the garden.","options":["helped","help"],"answer":"helped","full":"Yesterday, Sara helped her mum in the garden.","hint":"Yesterday is in the past. Add ed to help: helped.","explain":"Helped tells us Sara's action happened yesterday.","scene":"girl"},{"prompt":"Last night, I ___ to bed at nine.","options":["go","went"],"answer":"went","full":"Last night, I went to bed at nine.","hint":"Last night is in the past. Go changes to went.","explain":"Went is the past form of go.","scene":"boy"},{"prompt":"Yesterday, we ___ a small boat on the river.","options":["saw","see"],"answer":"saw","full":"Yesterday, we saw a small boat on the river.","hint":"Yesterday is in the past. See changes to saw.","explain":"Saw is the past form of see.","scene":"friends"},{"prompt":"Ali was able to swim at age four. He ___ swim when he was four.","options":["can","could"],"answer":"could","full":"He could swim when he was four.","hint":"The clue tells us about a past skill. Use could.","explain":"Could swim means he was able to swim in the past.","scene":"boy"},{"prompt":"Nora could ___ a bike when she was six.","options":["rode","ride"],"answer":"ride","full":"Nora could ride a bike when she was six.","hint":"Could already tells us about the past. Use ride after could.","explain":"Use the base verb ride after could: could ride.","scene":"girl"}]},{"id":"y4-portal","title":"Plan Portal","topic":"am / is / are going to · future plans","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"subtitle":"Make a plan for tomorrow","guide":"Read each plan. Tap the correct block to open tomorrow's portal!","taskLabel":"Plan portal opened","reminder":"For a plan, use am, is or are + going to + a verb. I am going to plant. She is going to plant. We are going to plant.","tasks":[{"prompt":"You plan to plant seeds tomorrow. I ___ going to plant seeds tomorrow.","options":["is","am"],"answer":"am","full":"I am going to plant seeds tomorrow.","hint":"Use am with I: I am going to plant.","explain":"I am going to plant describes your plan for tomorrow.","scene":"boy"},{"prompt":"Mira plans to read tonight. She ___ going to read tonight.","options":["is","are"],"answer":"is","full":"She is going to read tonight.","hint":"Use is with she: She is going to read.","explain":"She is going to read describes Mira's plan.","scene":"girl"},{"prompt":"The children plan to visit the park. They ___ going to visit the park.","options":["is","are"],"answer":"are","full":"They are going to visit the park.","hint":"Use are with they: They are going to visit.","explain":"They are going to visit describes the children's plan.","scene":"friends"},{"prompt":"We have a plan for tomorrow. We are going to ___ the cat.","options":["feed","fed"],"answer":"feed","full":"We are going to feed the cat.","hint":"After going to, use feed. Going to feed is the plan.","explain":"Use the base verb feed after going to.","scene":"friends"},{"prompt":"Choose the correct sentence for your plan to make a kite tomorrow.","options":["I going to make a kite tomorrow.","I am going to make a kite tomorrow.","I am going make a kite tomorrow."],"answer":"I am going to make a kite tomorrow.","full":"I am going to make a kite tomorrow.","hint":"You need I am going to make. Check for both am and to.","explain":"A complete plan uses am going to before the verb make.","scene":"boy"}]},{"id":"y4-rescue","title":"Reason Rescue","topic":"Why? · because · give a reason","type":"rune","color":"#ff9c95","icon":"cat","x":42,"y":22,"subtitle":"Explain how to help the cat","guide":"Read the cat's clue. Choose a reason to help the rescue team!","taskLabel":"Rescue reason explained","reminder":"Why asks for a reason. Because introduces a reason: We help the cat because it is cold.","tasks":[{"prompt":"Give a reason: The cat is hiding ___ it is afraid.","options":["because","and"],"answer":"because","full":"The cat is hiding because it is afraid.","hint":"Being afraid is the reason. Use because to give a reason.","explain":"Because links the cat's action to its reason: it is afraid.","scene":"friends"},{"prompt":"Ask for a reason: '___ is the cat wet?' 'Because it fell into the water.'","options":["Whose","Why"],"answer":"Why","full":"Why is the cat wet? Because it fell into the water.","hint":"The reply starts with Because. Ask for the reason with Why.","explain":"Why asks for a reason. Falling into the water explains why the cat is wet.","scene":"friends"},{"prompt":"The cat has no food. Choose the sentence that explains why it is hungry.","options":["The cat is hungry because it is full.","The cat is hungry because it has no food."],"answer":"The cat is hungry because it has no food.","full":"The cat is hungry because it has no food.","hint":"The clue says there is no food. Use that reason after because.","explain":"Having no food is the reason the cat is hungry. Because joins the two ideas.","scene":"friends"},{"prompt":"Give a reason for your opinion: I like this cat ___ it is friendly.","options":["but","because"],"answer":"because","full":"I like this cat because it is friendly.","hint":"Being friendly is your reason for liking the cat. Use because.","explain":"Because introduces a reason for your opinion.","scene":"boy"},{"prompt":"The cat is cold. Choose the sentence that gives the reason for a blanket.","options":["We give the cat a blanket because it is cold.","We give the cat a blanket because it is hot."],"answer":"We give the cat a blanket because it is cold.","full":"We give the cat a blanket because it is cold.","hint":"The clue says the cat is cold. Put that reason after because.","explain":"The cat is cold is the reason for giving it a blanket.","scene":"friends"}]},{"id":"y4-castle","title":"Comparison Castle","topic":"taller than · shorter than · bigger than · smaller than","type":"compare","color":"#e5b3f0","icon":"castle","x":89,"y":73,"subtitle":"Compare the castle objects","guide":"Look at the labels and sizes. Tap the object that matches the comparison!","taskLabel":"Castle comparison solved","reminder":"Taller and shorter compare heights. Bigger and smaller compare sizes. Than tells us which other object to compare with.","tasks":[{"prompt":"Look at the two towers. Tap the taller tower.","objects":[{"id":"a","label":"Tower A","size":80},{"id":"b","label":"Tower B","size":150}],"objectType":"tower","answer":"b","full":"Tower B is taller than Tower A.","hint":"Taller means higher. Tower B reaches higher than Tower A.","explain":"Tower B is taller than Tower A. We compare their heights."},{"prompt":"Look at the two chests. Tap the smaller chest.","objects":[{"id":"a","label":"Chest A","size":75},{"id":"b","label":"Chest B","size":130}],"objectType":"chest","answer":"a","full":"Chest A is smaller than Chest B.","hint":"Smaller means less big. Chest A is the little chest.","explain":"Chest A is smaller than Chest B. We compare their sizes."},{"prompt":"Find Tower A first. Tap the tower that is shorter than Tower A.","objects":[{"id":"a","label":"Tower A","size":110},{"id":"b","label":"Tower B","size":70},{"id":"c","label":"Tower C","size":155}],"objectType":"tower","answer":"b","full":"Tower B is shorter than Tower A.","hint":"Look for a tower lower than Tower A. Tower B is lower.","explain":"Tower B is shorter than Tower A. Tower C is taller than Tower A."},{"prompt":"Find Chest B first. Tap the chest that is bigger than Chest B.","objects":[{"id":"a","label":"Chest A","size":70},{"id":"b","label":"Chest B","size":105},{"id":"c","label":"Chest C","size":145}],"objectType":"chest","answer":"c","full":"Chest C is bigger than Chest B.","hint":"Look for a chest larger than Chest B. Chest C is larger.","explain":"Chest C is bigger than Chest B. Chest A is smaller than Chest B."},{"prompt":"Find Tower B first. Tap the tower that is taller than Tower B.","objects":[{"id":"a","label":"Tower A","size":75},{"id":"b","label":"Tower B","size":110},{"id":"c","label":"Tower C","size":155}],"objectType":"tower","answer":"c","full":"Tower C is taller than Tower B.","hint":"Look for a tower higher than Tower B. Tower C is higher.","explain":"Tower C is taller than Tower B. Tower A is shorter than Tower B."}]}],"rules":[["shop","Picnic amounts","many carrots · much milk · some bread · isn't any juice","Use many for things we count and much for an amount. These positive sentences use some. These negative sentences use any.","How many carrots are there? There is some bread. There isn't any juice."],["bridge","Who owns it?","hers · mine · yours · Whose ...? · Ali's","Mine, yours and hers can stand alone. Whose asks about an owner. Add 's for one owner, or an apostrophe after a plural ending in s.","Whose bike is this? It is Ali's bike. The cats' toys belong to the cats."],["train","Every day or now?","I feed every day. · I am feeding now.","A routine uses the present simple. An action happening now uses am, is or are and an -ing word.","Hana waters the flowers every day. The cat is sleeping now."],["boat","Activities and wishes","enjoy + ing · love + ing · want + to + verb","Use an -ing activity after enjoy. Love can also go with an -ing activity. Use to and a base verb after want.","I enjoy playing games. Aina wants to drink water."],["pickaxe","Past actions and skills","helped · went · saw · could + base verb","Some past verbs add ed. Others change: go becomes went and see becomes saw. Could tells us about a past ability.","Yesterday, Sara helped her mum. Nora could ride a bike when she was six."],["portal","Our plans","am / is / are + going to + base verb","Use going to for these future plans. Match am, is or are to the person. Keep the action verb in its base form.","I am going to plant seeds. They are going to visit the park."],["cat","Ask and give a reason","Why ...? · because + a reason","Why asks for a reason. Because explains the reason for an action or an opinion.","Why do you like the cat? I like it because it is friendly."],["castle","Compare two things","taller than · shorter than · bigger than · smaller than","Taller and shorter compare heights. Bigger and smaller compare sizes. Read which object comes after than before you choose.","Tower C is taller than Tower B. Chest A is smaller than Chest B."]],"curriculum":{"document":"KSSR (Semakan 2017) Standards-Based English Language Curriculum, Sekolah Kebangsaan, Year 4; Bahagian Pembangunan Kurikulum, Ministry of Education Malaysia, April 2018","title":"English Language Year 4 (SK) DSKP — Primary Year 4 Syllabus","url":"https://bpk.moe.gov.my/kurikulum/kssr/kssr-tahun-3-1/138-003-dskp-kssr-semakan-2017-bi-sk-thn4-print/file","grammarPages":"Printed syllabus pages 45–47 (PDF pages 59–61); earlier grammar in Appendix 1, printed pages 53–54 (PDF pages 67–68). Relevant learning standards: printed pages 26, 31 and 35–36 (PDF pages 40, 45 and 49–50).","learningStandards":["4.2.1: Language for giving reasons for simple opinions, supported here by because sentences.","4.2.3: Language for describing basic daily routines, supported here by guided sentence ordering.","4.2.4: Suitable language for describing people and objects, supported here by ownership and comparison statements.","4.3.1: Capital letters and sentence punctuation, practised here in guided word ordering; the full standard concerns writing at discourse level.","2.1.2: Language for describing past experiences; classroom speaking practice is needed to assess the full standard.","3.2.2: Reading for specific details is supported by short clues; the full standard expects simple texts of one or two paragraphs."],"note":"Original scaffolded practice for class 4K, using selected Year 4 SK grammar: quantities, ownership, verb + ing or infinitive, regular and irregular past forms, could, going to, why/because and short-adjective comparisons. The Year 4 syllabus explicitly recycles present simple and present continuous, used together here to contrast routines and actions now. Small choices, short word banks, direct hints, audio and retries support pupils step by step. This is a selected practice pack, not coverage of every Year 4 grammar item or a complete assessment of a DSKP learning standard or PBD performance level."}},"y5-high":{"year":5,"levelLabel":"Challenge","missions":[{"id":"y5-market","title":"Village Café","subtitle":"Check the supplies","topic":"much · many · there is / are · also","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"guide":"Read the café clues. Tap the correct message block to help the cooks!","taskLabel":"Café supply checked","tasks":[{"prompt":"The café has ten apples but only a little juice. Choose the message with correct grammar.","options":["There are many apples, but there isn't much juice.","There is many apples, but there aren't much juice.","There are much apples, but there isn't many juice."],"answer":"There are many apples, but there isn't much juice.","full":"There are many apples, but there isn't much juice.","hint":"Apples can be counted: many apples. Juice is a liquid: much juice. Match are to apples and is to juice.","explain":"Use many with countable apples and much with uncountable juice. The verb also matches the noun.","scene":"apple"},{"prompt":"The cook needs six bananas. You want to check the number of bananas on the table. Choose a correct question.","options":["How much bananas is there?","How many bananas are there?","How many banana is there?"],"answer":"How many bananas are there?","full":"How many bananas are there?","hint":"Ask How many about a number of things you can count. Bananas is plural.","explain":"How many asks for a number. Use the plural bananas and the question order are there.","scene":"apple"},{"prompt":"There are two bottles on the shelf. Both contain water. Fix the cook's note: 'There is two bottles of water.'","options":["There are two bottles of water.","There is two bottle of water.","There are two bottle of waters."],"answer":"There are two bottles of water.","full":"There are two bottles of water.","hint":"The sentence counts bottles, not the water inside them. Two bottles needs are.","explain":"Bottles is the plural noun that controls the verb. Use There are two bottles of water.","scene":"friends"},{"prompt":"The cook has plenty of rice. She does not know the amount of rice needed for the meal. Choose the question to ask her.","options":["How many rice do we need?","How much rices do we need?","How much rice do we need?"],"answer":"How much rice do we need?","full":"How much rice do we need?","hint":"Rice is uncountable here. Ask about its amount with How much.","explain":"Use How much with uncountable rice. Do not add s to rice.","scene":"friends"},{"prompt":"Ravi enjoys fruit. He enjoys sandwiches too. Choose the correct sentence that adds this second fact using also.","options":["He also enjoy sandwiches.","He also enjoys sandwiches.","He also enjoying sandwiches."],"answer":"He also enjoys sandwiches.","full":"Ravi enjoys fruit. He also enjoys sandwiches.","hint":"Also adds another fact. A routine or preference with he needs enjoys.","explain":"Also adds the second preference. Use enjoys after he in the present simple.","scene":"boy"}]},{"id":"y5-bridge","title":"Message Bridge","subtitle":"Connect the explorers","topic":"object pronouns · and · or · but · so · because","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"guide":"Choose messages that connect ideas clearly. Each correct message builds the bridge!","taskLabel":"Message delivered","tasks":[{"prompt":"Mina dropped two maps. You picked up both maps. Complete her message: 'I dropped the maps, so you picked ___ up.'","options":["they","him","them"],"answer":"them","full":"I dropped the maps, so you picked them up.","hint":"Both maps is plural. The word after picked refers to the things that received the action.","explain":"Them is an object pronoun for the two maps. They is a subject pronoun.","scene":"girl"},{"prompt":"Ravi can run fast. He cannot climb the high wall. Choose the word that shows this contrast: 'He can run fast, ___ he cannot climb the wall.'","options":["but","because","so"],"answer":"but","full":"He can run fast, but he cannot climb the wall.","hint":"You need a word that contrasts an ability with something he cannot do.","explain":"But connects contrasting ideas: he can do one thing, but he cannot do the other.","scene":"boy"},{"prompt":"Only one route can open. The team must choose between the train and the boat. Complete the choice: 'We can take the train ___ the boat.'","options":["so","and","or"],"answer":"or","full":"We can take the train or the boat.","hint":"The team has two alternatives and must choose one.","explain":"Or presents alternatives. And would join both forms of transport rather than show this choice.","scene":"friends"},{"prompt":"The bridge was broken. As a result, the team took the boat. Choose the word that shows the result: 'The bridge was broken, ___ we took the boat.'","options":["because","so","or"],"answer":"so","full":"The bridge was broken, so we took the boat.","hint":"The first part gives a problem. The second part tells you what happened as a result.","explain":"So introduces the result of the broken bridge: the team took the boat.","scene":"friends"},{"prompt":"Aisha is lost. Ben gives Aisha a map. Choose the sentence that uses the correct pronouns and gives the reason.","options":["Ben gives she a map because her is lost.","Ben gives him a map because she is lost.","Ben gives her a map because she is lost."],"answer":"Ben gives her a map because she is lost.","full":"Ben gives her a map because she is lost.","hint":"Aisha receives the map: use her. Aisha is the subject of is lost: use she. Because introduces the reason.","explain":"Use object pronoun her after gives and subject pronoun she before is. Because explains why Ben gives the map.","scene":"girl"}]},{"id":"y5-train","title":"Timetable Train","subtitle":"Build questions and routines","topic":"What time · How often · frequency · present simple","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"guide":"Use the clues to build each question or routine. Put every carriage in the correct order!","taskLabel":"Timetable message ready","tasks":[{"prompt":"Nora checks her compass every morning. Ask about the frequency of this action. Start with How and finish with compass?","words":["How","often","does","Nora","check","her","compass?"],"answer":"How often does Nora check her compass?","full":"How often does Nora check her compass?","hint":"Use How often to ask about frequency. Put does before Nora, then use check without s.","explain":"How often asks about frequency. In a present simple question, does is followed by the subject and the base verb.","scene":"girl"},{"prompt":"You know the train leaves in the morning, but you need its exact departure time. Build a question. Start with What and finish with leave?","words":["What","time","does","the","train","leave?"],"answer":"What time does the train leave?","full":"What time does the train leave?","hint":"Use What time for an exact time. Use does with the train, then the base verb leave.","explain":"What time asks for the departure time. After does, use leave rather than leaves.","scene":"friends"},{"prompt":"Mina visits the market on most days, but not every day. Build her routine with usually before the main verb. Start with Mina.","words":["Mina","usually","visits","the","market."],"answer":"Mina usually visits the market.","full":"Mina usually visits the market.","hint":"Usually means on most occasions. Place it before visits.","explain":"Usually expresses a regular action that does not happen every time. It comes before the main verb visits.","scene":"girl"},{"prompt":"The boat operates on Tuesdays and Fridays. It is closed on Mondays. Build the negative routine. Start with The and finish with Mondays.","words":["The","boat","does","not","sail","on","Mondays."],"answer":"The boat does not sail on Mondays.","full":"The boat does not sail on Mondays.","hint":"Use does not with the boat. The verb after does not is sail, without s.","explain":"Does not sail is the correct present simple negative for the boat. On Mondays tells us about a repeated routine.","scene":"friends"},{"prompt":"Your team is ready for every adventure. Build a sentence using always directly after are. Start with We and finish with adventure.","words":["We","are","always","ready","for","adventure."],"answer":"We are always ready for adventure.","full":"We are always ready for adventure.","hint":"A frequency adverb usually comes after am, is or are. Put always after are.","explain":"Always means every time. With the verb be, place the frequency adverb after the verb: are always.","scene":"friends"}]},{"id":"y5-river","title":"River Instructions","subtitle":"Guide the boat crew","topic":"imperatives · negative instructions · sequencing","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"guide":"Build clear instructions for the crew. Use the order clues to launch the boat!","taskLabel":"Crew instruction ready","tasks":[{"prompt":"Before a trip, the crew prepares drinking water. Build the first instruction. Start with First, and finish with water.","words":["First,","fill","the","bottle","with","clean","water."],"answer":"First, fill the bottle with clean water.","full":"First, fill the bottle with clean water.","hint":"First introduces the opening step. An instruction begins with a base verb such as fill.","explain":"First marks the start of the sequence. Fill is an imperative that tells the crew what to do.","scene":"friends"},{"prompt":"Running on the narrow bridge is unsafe. Build a clear negative instruction for the crew. Start with Do and finish with bridge.","words":["Do","not","run","on","the","bridge."],"answer":"Do not run on the bridge.","full":"Do not run on the bridge.","hint":"A negative instruction starts with Do not. Follow it with the base verb run.","explain":"Do not run is a negative imperative. It gives a clear instruction to avoid the unsafe action.","scene":"boy"},{"prompt":"The crew has put soil in a pot and added a seed. Now build the last instruction. Start with Finally, and finish with pot.","words":["Finally,","water","the","seed","in","the","pot."],"answer":"Finally, water the seed in the pot.","full":"Finally, water the seed in the pot.","hint":"Finally introduces the last step. Water is a verb here: it tells someone to give water to the seed.","explain":"Finally marks the end of the sequence. Water the seed is an imperative instruction.","scene":"friends"},{"prompt":"Before walking to the boat, explorers must check their map, then follow the path. Join the two instructions. Start with Check and finish with path.","words":["Check","your","map","and","follow","the","path."],"answer":"Check your map and follow the path.","full":"Check your map and follow the path.","hint":"Check and follow are instruction verbs. And joins the two instructions.","explain":"Both actions use the base verb because they are imperatives. And links the two steps.","scene":"friends"},{"prompt":"First, fold the map. The second step is to put it in your bag. Build that second instruction. Start with Next, and finish with bag.","words":["Next,","put","the","map","in","your","bag."],"answer":"Next, put the map in your bag.","full":"Next, put the map in your bag.","hint":"Next introduces the following step. Start the instruction itself with put.","explain":"Next shows the order of the steps. Put the map in your bag tells the explorer what to do after folding the map.","scene":"boy"}]},{"id":"y5-mine","title":"Story Mine","subtitle":"Repair the adventure diary","topic":"past simple · questions · negatives · past and now","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"guide":"Read the diary clues. Mine the correct sentence block to repair the story!","taskLabel":"Diary page repaired","tasks":[{"prompt":"The team searched the mine yesterday. They found no gold. Fix this diary sentence: 'We did not found any gold.'","options":["We did not find any gold.","We did not finds any gold.","We did not finding any gold."],"answer":"We did not find any gold.","full":"We did not find any gold.","hint":"Did not already shows the past. Use the base verb find after it.","explain":"A past simple negative uses did not plus the base verb. Found becomes find after did not.","scene":"friends"},{"prompt":"Rina joined the team yesterday. You are checking what she brought on that trip. Choose the correct past-tense question about the rope.","options":["Does she bring the rope yesterday?","Did she bring the rope?","Did she brought the rope?"],"answer":"Did she bring the rope?","full":"Did she bring the rope?","hint":"Ask about yesterday with Did. Follow the subject with the base verb bring.","explain":"Did marks the question as past simple. Use bring, not brought, after did.","scene":"girl"},{"prompt":"The diary says: First, we entered the mine. Next, we found a gem. After that, we went home. Choose the grammatically correct final diary sentence.","options":["After that, we go home yesterday.","After that, we goed home.","After that, we went home."],"answer":"After that, we went home.","full":"After that, we went home.","hint":"All three events are finished. Go has the irregular past form went.","explain":"Went is the past form of go. After that places this event after finding the gem.","scene":"friends"},{"prompt":"Last Saturday, the explorers made a safe path from wooden blocks. Complete their report: 'We ___ a safe path.'","options":["builded","built","build"],"answer":"built","full":"We built a safe path.","hint":"Last Saturday is a finished time. Build is irregular in the past: built.","explain":"Use built for the completed action last Saturday. Not all past-tense verbs end in ed.","scene":"friends"},{"prompt":"The adventure happened yesterday. The team is taking a rest at this moment. Choose the message that shows both times correctly.","options":["Yesterday, we explored the mine. Now, we are resting.","Yesterday, we explore the mine. Now, we rested.","Yesterday, we exploring the mine. Now, we are rest."],"answer":"Yesterday, we explored the mine. Now, we are resting.","full":"Yesterday, we explored the mine. Now, we are resting.","hint":"A finished action yesterday needs the past simple. An action happening now needs are plus an ing verb.","explain":"Explored describes the finished adventure. Are resting describes what the team is doing now.","scene":"friends"}]},{"id":"y5-portal","title":"Future Portal","subtitle":"Make plans and promises","topic":"will / won't · predictions · promises · going to","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"guide":"Read each future clue. Choose a clear plan, prediction or promise to open the portal!","taskLabel":"Future message ready","tasks":[{"prompt":"Your friend cannot carry the heavy boxes alone. Choose a grammatically correct promise to help with the boxes tomorrow.","options":["I will helped you carry the boxes tomorrow.","I will help you carry the boxes tomorrow.","I will helping you carry the boxes tomorrow."],"answer":"I will help you carry the boxes tomorrow.","full":"I will help you carry the boxes tomorrow.","hint":"Use will for the promise. The verb immediately after will must be the base form help.","explain":"Will help expresses the promise. Will is followed by a base verb, even when the action is tomorrow.","scene":"friends"},{"prompt":"The weather report predicts heavy rain tomorrow. The team decides to stay indoors. Choose a message that matches the report and has correct grammar.","options":["It won't rain tomorrow, so we will stay indoors.","It will rains tomorrow, so we will stay indoors.","It will rain tomorrow, so we will stay indoors."],"answer":"It will rain tomorrow, so we will stay indoors.","full":"It will rain tomorrow, so we will stay indoors.","hint":"The prediction is rain, not no rain. After will, use rain without s. So introduces the team's decision.","explain":"Will rain gives the prediction. Will stay uses another base verb, and so connects the prediction to the decision.","scene":"friends"},{"prompt":"Mei has bought seeds and prepared pots. She has a plan for tomorrow. Choose the correct sentence describing that plan.","options":["She is going to plant the seeds tomorrow.","She are going to plant the seeds tomorrow.","She is going to planted the seeds tomorrow."],"answer":"She is going to plant the seeds tomorrow.","full":"She is going to plant the seeds tomorrow.","hint":"For this plan, use She is going to followed by the base verb plant.","explain":"Is going to plant describes Mei's planned action. Use is with she and the base verb after going to.","scene":"girl"},{"prompt":"A bird has a broken wing. The vet predicts it will need several days of rest. Choose a grammatically correct negative prediction for today.","options":["It won't flew today.","It won't fly today.","It won't flying today."],"answer":"It won't fly today.","full":"It won't fly today.","hint":"Won't means will not. It is followed by the base verb fly.","explain":"Won't fly is a negative prediction. Use fly rather than flew or flying after won't.","scene":"friends"},{"prompt":"The explorers have made a plan for next week. You want to check whether their plan is to visit the village. Choose the correctly formed question.","options":["Are they going to visiting the village?","Is they going to visit the village?","Are they going to visit the village?"],"answer":"Are they going to visit the village?","full":"Are they going to visit the village?","hint":"Use are with they. In the question, place Are before they and use visit after going to.","explain":"Are they going to visit is the question form of They are going to visit. The main verb stays in its base form.","scene":"friends"}]},{"id":"y5-rescue","title":"Rescue Camp","subtitle":"Use your skills and ask permission","topic":"can / can't · ability · permission · verb + ing","type":"rune","color":"#ff9c95","icon":"cat","x":46,"y":31,"guide":"Choose the right rescue message. Think about skills, permission and what each explorer enjoys!","taskLabel":"Rescue plan approved","tasks":[{"prompt":"Mina climbs trees easily, but she is unable to swim. Choose a correct sentence that reports both abilities.","options":["Mina can climb, but she can't swim.","Mina cans climb, but she can't swim.","Mina can swim, but she can't climb."],"answer":"Mina can climb, but she can't swim.","full":"Mina can climb, but she can't swim.","hint":"Can describes an ability. Can't describes something she is unable to do. Do not add s to can.","explain":"Can climb and can't swim match the clues. Can has the same form with every subject.","scene":"girl"},{"prompt":"You need the teacher's book for the rescue plan. Choose a grammatically correct, polite question asking permission to use it.","options":["Can I using your book, please?","Can I use your book, please?","Can I uses your book, please?"],"answer":"Can I use your book, please?","full":"Can I use your book, please?","hint":"A permission question starts Can I. Put the base verb use after I.","explain":"Can I use asks permission. Please makes the request polite. The verb after can stays in its base form.","scene":"boy"},{"prompt":"The path is closed. The captain refuses the request, 'Can we use this path?' Choose the reply that clearly refuses permission.","options":["No, you can. The path is closed.","No, you don't. The path is closed.","No, you can't. The path is closed."],"answer":"No, you can't. The path is closed.","full":"No, you can't. The path is closed.","hint":"Match a question with can to a short answer with can or can't. Refusing permission needs can't.","explain":"No, you can't refuses permission. The closed path gives the reason.","scene":"friends"},{"prompt":"The captain owns a locked chest. Your team must ask permission before opening it. Choose a correctly formed question from the team.","options":["Can we open the chest?","Can we opening the chest?","Can we opens the chest?"],"answer":"Can we open the chest?","full":"Can we open the chest?","hint":"For the standard question form, put Can before we, then add the base verb open.","explain":"Can we open is the standard question order for requesting permission. Use open rather than opens.","scene":"friends"},{"prompt":"Ben likes swimming, but he dislikes running. Choose the sentence that expresses his preferences and has correct grammar.","options":["He enjoys swim, but he does not like running.","He enjoys swimming, but he does not like running.","He enjoys running, but he does not like swimming."],"answer":"He enjoys swimming, but he does not like running.","full":"He enjoys swimming, but he does not like running.","hint":"Enjoy is followed by a verb ending in ing. Check that both activities match Ben's preferences.","explain":"Enjoys swimming uses the ing form after enjoy. But connects Ben's contrasting preferences.","scene":"boy"}]},{"id":"y5-castle","title":"Castle Logic","subtitle":"Solve the comparison clues","topic":"comparatives · superlatives · connected clues","type":"compare","color":"#e5b3f0","icon":"castle","x":62,"y":13,"guide":"Use every comparison clue. Tap the tower or chest that meets the whole instruction!","taskLabel":"Castle clue solved","tasks":[{"prompt":"The scout needs a tower taller than Tower A but shorter than Tower C. Choose the tower that meets both clues.","answer":"b","full":"Tower B is taller than Tower A but shorter than Tower C.","objects":[{"id":"a","label":"Tower A","size":76},{"id":"b","label":"Tower B","size":113},{"id":"c","label":"Tower C","size":154}],"hint":"You need the middle height. The answer cannot be the shortest or the tallest tower.","explain":"Tower B meets both comparisons: it is taller than A and shorter than C."},{"prompt":"The boat needs a chest bigger than Chest A but smaller than Chest B. Choose a chest that meets both size clues.","answer":"c","full":"Chest C is bigger than Chest A but smaller than Chest B.","objectType":"chest","objects":[{"id":"a","label":"Chest A","size":76},{"id":"b","label":"Chest B","size":150},{"id":"c","label":"Chest C","size":112}],"hint":"Compare all three chests. Look for a chest in the middle of the two named sizes.","explain":"Chest C is the middle size. Bigger and smaller compare it with the two other chests."},{"prompt":"Tower C is taller than Tower B. Tower A is shorter than Tower B. Choose the second-tallest tower.","answer":"b","full":"Tower B is the second-tallest tower.","objects":[{"id":"a","label":"Tower A","size":76},{"id":"b","label":"Tower B","size":116},{"id":"c","label":"Tower C","size":155}],"hint":"First find the tallest tower. The next tower in height is the second-tallest.","explain":"C is tallest and A is shortest. B is the second-tallest because it is between them in height."},{"prompt":"The ladder reaches only towers shorter than Tower B. Of those towers, choose the tallest one it can reach.","answer":"c","full":"Tower C is the tallest tower that is shorter than Tower B.","objects":[{"id":"a","label":"Tower A","size":76},{"id":"b","label":"Tower B","size":155},{"id":"c","label":"Tower C","size":117}],"hint":"Leave out Tower B first. Then compare the heights of the two remaining towers.","explain":"A and C are shorter than B. C is the taller of those two, so it is the tallest tower the ladder can reach."},{"prompt":"The smallest chest is too small. The biggest chest is too heavy. Choose a chest that is not the smallest and not the biggest.","answer":"a","full":"Chest A is bigger than Chest B but smaller than Chest C.","objectType":"chest","objects":[{"id":"a","label":"Chest A","size":113},{"id":"b","label":"Chest B","size":76},{"id":"c","label":"Chest C","size":150}],"hint":"Cross out the smallest and biggest chests. Only the middle-sized chest remains.","explain":"Chest A is the middle size. It avoids both problems because it is not the smallest or the biggest."}]}],"rules":[["shop","Café quantities","many apples · much juice · there are bottles","Use many for things you can count and much for an uncountable amount. Match is or are to the noun you describe. Also adds another fact.","There are many apples, but there isn't much juice. He also enjoys sandwiches."],["bridge","Pronouns and links","him / her / them · and / or / but / so / because","Object pronouns receive an action. And adds, or gives a choice, but contrasts, so gives a result and because gives a reason.","Aisha is lost. Ben gives her a map because she needs help."],["train","Questions and frequency","How often does ...? · What time does ...?","Ask about frequency with How often and a time with What time. Use a base verb after does. Frequency words usually come before a main verb and after be.","How often does Nora check her compass? We are always ready."],["boat","Instructions in order","First, ... Next, ... Finally, ... · Do not + base verb","Start an instruction with a base verb. Use Do not for a negative instruction. Sequencing words make the steps clear.","First, check your map. Next, follow the path. Do not run on the bridge."],["pickaxe","Past and now","built · went · did not find · Did she bring ...?","Use past simple for finished events. After did or did not, use a base verb. For an action happening now, use am, is or are plus an ing verb.","Yesterday, we explored the mine. Now, we are resting."],["portal","Future messages","will / won't + base verb · be going to + base verb","Use will for predictions and promises. Won't means will not. Going to describes a plan. Match am, is or are to the subject.","I will help you tomorrow. She is going to plant seeds."],["cat","Skills and permission","can / can't + base verb · Can we ...? · enjoy + verb-ing","Can describes an ability or asks permission. Can't can show inability or refuse permission. Keep the next verb in its base form. Use an ing verb after enjoy.","Can we open the chest? He enjoys swimming."],["castle","Comparison clues","taller than · smaller than · the tallest · the smallest","Comparatives compare things. Superlatives identify an extreme in a group. When there are two clues, your choice must satisfy both of them.","Tower B is taller than Tower A but shorter than Tower C."]],"curriculum":{"document":"KSSR (Semakan 2017) Standards-Based English Language Curriculum, Sekolah Kebangsaan, Year 5; Bahagian Pembangunan Kurikulum, Ministry of Education Malaysia, November 2020","title":"Year 5 DSKP grammar practice","url":"https://www.teacherfiera.com/wp-content/uploads/2020/04/DSKP-ENGLISH-YEAR-5-SK-30-12-2020-Latest.pdf","grammarPages":"Printed syllabus pages 45–46; PDF pages 59–60","learningStandards":[{"code":"2.1.3 / 4.2.2","focus":"Language for asking for and giving simple advice."},{"code":"2.1.4","focus":"Language for questions and descriptions about future plans."},{"code":"2.1.5 / 4.2.4","focus":"Suitable statements describing people, places and things."},{"code":"2.2.1","focus":"Suitable questions for short exchanges."},{"code":"4.2.3","focus":"Language for recounting real events and experiences."},{"code":"4.2.5","focus":"Links between ideas using coordinating conjunctions and reference pronouns."},{"code":"4.3.3","focus":"Checking and improving a draft after feedback."}],"note":"Original contextual grammar activities for a higher-ability class, within the Year 5 syllabus and its stated review of earlier grammar. These short practice tasks support selected language skills; game scores are not a complete assessment of the DSKP learning standards or a PBD performance level."}},"y6-supported":{"year":6,"levelLabel":"Step by step","missions":[{"id":"market","title":"Village Market","topic":"am · is · are · have · has","type":"rune","color":"#ffbd64","icon":"shop","x":18,"y":72,"guide":"Tap the correct word block. Help the villagers open their shops!","taskLabel":"Shop opened","tasks":[{"prompt":"I ___ happy.","options":["am","is","are"],"answer":"am","full":"I am happy.","hint":"Use am with I. Use is with he, she or it. Use are with you, we or they.","explain":"I am happy. Use am after I.","scene":"boy","dskpTopic":"Recycled Years 1–5 be and have foundations; Year 6 syllabus sections 9–10 permit earlier grammar review","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"She ___ a teacher.","options":["are","is","am"],"answer":"is","full":"She is a teacher.","hint":"She is one person. Use is with she.","explain":"She is a teacher. Use is after she.","scene":"girl","dskpTopic":"Recycled Years 1–5 be and have foundations; Year 6 syllabus sections 9–10 permit earlier grammar review","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"They ___ my friends.","options":["is","am","are"],"answer":"are","full":"They are my friends.","hint":"Use are with they.","explain":"They are my friends. Use are after they.","scene":"friends","dskpTopic":"Recycled Years 1–5 be and have foundations; Year 6 syllabus sections 9–10 permit earlier grammar review","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"He ___ a red bag.","options":["have","has"],"answer":"has","full":"He has a red bag.","hint":"Use has with he, she or it. Use have with I, you, we or they.","explain":"He has a red bag. Use has after he.","scene":"boy","dskpTopic":"Recycled Years 1–5 be and have foundations; Year 6 syllabus sections 9–10 permit earlier grammar review","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"We ___ two books.","options":["has","have"],"answer":"have","full":"We have two books.","hint":"Use have with we.","explain":"We have two books. Use have after we.","scene":"friends","dskpTopic":"Recycled Years 1–5 be and have foundations; Year 6 syllabus sections 9–10 permit earlier grammar review","learningStandard":"4.2.1 (preparatory language support)"}],"subtitle":"Help the village"},{"id":"bridge","title":"Pronoun Bridge","topic":"he · she · they · his · her","type":"bridge","color":"#80d4ea","icon":"bridge","x":38,"y":56,"guide":"Tap the correct pronoun block to build the bridge. Help your friends cross!","taskLabel":"Bridge block added","tasks":[{"prompt":"Ali is a boy. ___ is kind.","options":["He","She","They"],"answer":"He","full":"Ali is a boy. He is kind.","hint":"Use he for one boy.","explain":"He takes the place of Ali, a boy.","scene":"boy","dskpTopic":"Recycled subject pronouns and possessive adjectives; Year 6 syllabus sections 9–10 and Appendix 1","learningStandard":"4.2.1 / 4.2.5 (preparatory language support)"},{"prompt":"Sara is a girl. ___ is reading.","options":["He","She","They"],"answer":"She","full":"Sara is a girl. She is reading.","hint":"Use she for one girl.","explain":"She takes the place of Sara, a girl.","scene":"girl","dskpTopic":"Recycled subject pronouns and possessive adjectives; Year 6 syllabus sections 9–10 and Appendix 1","learningStandard":"4.2.1 / 4.2.5 (preparatory language support)"},{"prompt":"Ali and Sara are friends. ___ play together.","options":["He","She","They"],"answer":"They","full":"Ali and Sara are friends. They play together.","hint":"Use they for two or more people.","explain":"Use They for Ali and Sara. There are two people.","scene":"friends","dskpTopic":"Recycled subject pronouns and possessive adjectives; Year 6 syllabus sections 9–10 and Appendix 1","learningStandard":"4.2.1 / 4.2.5 (preparatory language support)"},{"prompt":"This bag belongs to Ali. It is ___ bag.","options":["his","her","their"],"answer":"his","full":"This bag belongs to Ali. It is his bag.","hint":"The bag belongs to Ali. Use his before bag.","explain":"His bag means the bag belongs to Ali.","scene":"boy","dskpTopic":"Recycled subject pronouns and possessive adjectives; Year 6 syllabus sections 9–10 and Appendix 1","learningStandard":"4.2.1 / 4.2.5 (preparatory language support)"},{"prompt":"This book belongs to Sara. It is ___ book.","options":["his","her","their"],"answer":"her","full":"This book belongs to Sara. It is her book.","hint":"The book belongs to Sara. Use her before book.","explain":"Her book means the book belongs to Sara.","scene":"girl","dskpTopic":"Recycled subject pronouns and possessive adjectives; Year 6 syllabus sections 9–10 and Appendix 1","learningStandard":"4.2.1 / 4.2.5 (preparatory language support)"}],"subtitle":"Help your friends cross"},{"id":"train","title":"Word Train","topic":"Simple Present","type":"train","color":"#a8d884","icon":"train","x":17,"y":34,"guide":"Tap the word carriages in order. Build a sentence to move the train!","taskLabel":"Train journey completed","tasks":[{"prompt":"Talk about playing football every day. Start with I.","words":["I","play","football","every","day."],"answer":"I play football every day.","full":"I play football every day.","hint":"Start with I. Put play next. Finish with every day.","explain":"I play football every day. Every day tells us this is a routine.","scene":"ball","dskpTopic":"Recycled present simple for routines; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"Talk about her trip to school. Start with She.","words":["She","walks","to","school."],"answer":"She walks to school.","full":"She walks to school.","hint":"Start with She. For a routine, use walks after she.","explain":"She walks to school. Add s to walk after she.","scene":"girl","dskpTopic":"Recycled present simple for routines; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"Talk about eating rice every day. Start with They.","words":["They","eat","rice","every","day."],"answer":"They eat rice every day.","full":"They eat rice every day.","hint":"Start with They. Put eat next. Finish with every day.","explain":"They eat rice every day. Use eat after they.","scene":"friends","dskpTopic":"Recycled present simple for routines; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"Talk about the fruit he likes. Start with He.","words":["He","likes","apples."],"answer":"He likes apples.","full":"He likes apples.","hint":"Start with He. Put likes next.","explain":"He likes apples. Add s to like after he.","scene":"boy","dskpTopic":"Recycled present simple for routines; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"Talk about going to school on Mondays. Start with We.","words":["We","go","to","school","on","Mondays."],"answer":"We go to school on Mondays.","full":"We go to school on Mondays.","hint":"Start with We go. Finish with on Mondays.","explain":"We go to school on Mondays. Use go after we.","scene":"friends","dskpTopic":"Recycled present simple for routines; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"}],"subtitle":"Build your daily routine"},{"id":"river","title":"Action River","topic":"Present Continuous","type":"build","color":"#69c8e8","icon":"boat","x":56,"y":74,"guide":"Put the word blocks in order to build a boat. These actions are happening now!","taskLabel":"Boat launched","tasks":[{"prompt":"The boy is running now. Build the sentence. Start with He.","words":["He","is","running."],"answer":"He is running.","full":"He is running.","hint":"Start with He is. Then add running.","explain":"He is running. Use is + running for an action happening now.","scene":"boy","dskpTopic":"Recycled present continuous; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"The girl is reading now. Build the sentence. Start with She.","words":["She","is","reading","a","book."],"answer":"She is reading a book.","full":"She is reading a book.","hint":"Start with She is. Put reading next.","explain":"She is reading a book. Use is + reading after she.","scene":"girl","dskpTopic":"Recycled present continuous; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"Your friends are playing now. Build the sentence. Start with They.","words":["They","are","playing","football."],"answer":"They are playing football.","full":"They are playing football.","hint":"Start with They are. Put playing next.","explain":"They are playing football. Use are + playing after they.","scene":"ball","dskpTopic":"Recycled present continuous; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"You are eating an apple now. Build the sentence. Start with I.","words":["I","am","eating","an","apple."],"answer":"I am eating an apple.","full":"I am eating an apple.","hint":"Start with I am. Put eating next.","explain":"I am eating an apple. Use am + eating after I.","scene":"apple","dskpTopic":"Recycled present continuous; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"},{"prompt":"You and your friends are watching TV now. Start with We.","words":["We","are","watching","TV."],"answer":"We are watching TV.","full":"We are watching TV.","hint":"Start with We are. Put watching next.","explain":"We are watching TV. Use are + watching after we.","scene":"friends","dskpTopic":"Recycled present continuous; Year 4 routine-versus-current-action function in Year 6 Appendix 1","learningStandard":"4.2.1 (preparatory language support)"}],"subtitle":"Build actions happening now"},{"id":"mine","title":"Yesterday Mine","topic":"Simple Past","type":"mine","color":"#acbcdf","icon":"pickaxe","x":68,"y":51,"guide":"Mine the correct past-tense word block. Each correct answer gives you a gem!","taskLabel":"Gem found","tasks":[{"prompt":"Yesterday, I ___ football.","options":["play","played","playing"],"answer":"played","full":"Yesterday, I played football.","hint":"Yesterday is in the past. Play becomes played.","explain":"Played is the past form of play.","scene":"ball","dskpTopic":"Recycled past simple, regular and irregular; Year 4 grammar in Year 6 Appendix 1","learningStandard":"4.2.3 (preparatory language support)"},{"prompt":"Last night, she ___ TV.","options":["watch","watches","watched"],"answer":"watched","full":"Last night, she watched TV.","hint":"Last night is in the past. Watch becomes watched.","explain":"Watched tells us the action happened last night.","scene":"girl","dskpTopic":"Recycled past simple, regular and irregular; Year 4 grammar in Year 6 Appendix 1","learningStandard":"4.2.3 (preparatory language support)"},{"prompt":"Yesterday, he ___ to school.","options":["go","went","goes"],"answer":"went","full":"Yesterday, he went to school.","hint":"Yesterday is in the past. Go becomes went.","explain":"Went is the past form of go.","scene":"boy","dskpTopic":"Recycled past simple, regular and irregular; Year 4 grammar in Year 6 Appendix 1","learningStandard":"4.2.3 (preparatory language support)"},{"prompt":"Yesterday, we ___ rice.","options":["eat","ate","eating"],"answer":"ate","full":"Yesterday, we ate rice.","hint":"Yesterday is in the past. Eat becomes ate.","explain":"Ate is the past form of eat.","scene":"friends","dskpTopic":"Recycled past simple, regular and irregular; Year 4 grammar in Year 6 Appendix 1","learningStandard":"4.2.3 (preparatory language support)"},{"prompt":"Last Sunday, they ___ their grandma.","options":["visit","visited","visits"],"answer":"visited","full":"Last Sunday, they visited their grandma.","hint":"Last Sunday is in the past. Add ed to visit.","explain":"Visited tells us the visit happened in the past.","scene":"friends","dskpTopic":"Recycled past simple, regular and irregular; Year 4 grammar in Year 6 Appendix 1","learningStandard":"4.2.3 (preparatory language support)"}],"subtitle":"Find words from the past"},{"id":"portal","title":"Tomorrow Portal","topic":"will · going to","type":"portal","color":"#bea1fa","icon":"portal","x":80,"y":27,"guide":"Tap the correct word to open the portal. Help your explorer travel to tomorrow!","taskLabel":"Portal opened","tasks":[{"prompt":"Tomorrow, I ___ help my mum.","options":["will","was","did"],"answer":"will","full":"Tomorrow, I will help my mum.","hint":"Tomorrow is in the future. Use will before help.","explain":"Will help tells us about an action in the future.","scene":"boy","dskpTopic":"Year 6 future forms: will and going to; also recycled Year 4–5 grammar","learningStandard":"4.2.2 (preparatory language support)"},{"prompt":"Next week, she will ___ her grandma.","options":["visits","visit","visited"],"answer":"visit","full":"Next week, she will visit her grandma.","hint":"After will, use the base form of the verb: visit.","explain":"Use visit after will. This action will happen next week.","scene":"girl","dskpTopic":"Year 6 future forms: will and going to; also recycled Year 4–5 grammar","learningStandard":"4.2.2 (preparatory language support)"},{"prompt":"I ___ going to read a book tonight.","options":["is","are","am"],"answer":"am","full":"I am going to read a book tonight.","hint":"Use I + am + going to + a verb.","explain":"I am going to read a book tonight. This is a plan for tonight.","scene":"boy","dskpTopic":"Year 6 future forms: will and going to; also recycled Year 4–5 grammar","learningStandard":"4.2.2 (preparatory language support)"},{"prompt":"They are going to ___ football tomorrow.","options":["played","play","plays"],"answer":"play","full":"They are going to play football tomorrow.","hint":"After going to, use the base form of the verb: play.","explain":"Going to play tells us about a plan for tomorrow.","scene":"ball","dskpTopic":"Year 6 future forms: will and going to; also recycled Year 4–5 grammar","learningStandard":"4.2.2 (preparatory language support)"},{"prompt":"We ___ going to visit the zoo tomorrow.","options":["am","is","are"],"answer":"are","full":"We are going to visit the zoo tomorrow.","hint":"Use are with we.","explain":"We are going to visit the zoo tomorrow. Use are after we.","scene":"friends","dskpTopic":"Year 6 future forms: will and going to; also recycled Year 4–5 grammar","learningStandard":"4.2.2 (preparatory language support)"}],"subtitle":"Travel to tomorrow"},{"id":"rescue","title":"Animal Rescue","topic":"in · on · under · behind · between","type":"place","color":"#ff9c95","icon":"cat","x":42,"y":22,"guide":"Tap the cat, then tap the correct place. You can also drag the cat to its place!","taskLabel":"Cat rescued","tasks":[{"prompt":"The cat is in the box.","answer":"in","full":"The cat is in the box.","hint":"In means inside. Find the inside of the box.","explain":"In the box means inside the box.","dskpTopic":"Recycled location and position; Year 6 language function 8 and earlier primary prepositions","learningStandard":"3.2.2 (preparatory language support)"},{"prompt":"The cat is on the table.","answer":"on","full":"The cat is on the table.","hint":"On means on top. Find the top of the table.","explain":"On the table means on top of the table.","dskpTopic":"Recycled location and position; Year 6 language function 8 and earlier primary prepositions","learningStandard":"3.2.2 (preparatory language support)"},{"prompt":"The cat is under the table.","answer":"under","full":"The cat is under the table.","hint":"Under means below. Find the space below the table.","explain":"Under the table means below the table.","dskpTopic":"Recycled location and position; Year 6 language function 8 and earlier primary prepositions","learningStandard":"3.2.2 (preparatory language support)"},{"prompt":"The cat is behind the tree.","answer":"behind","full":"The cat is behind the tree.","hint":"Behind means at the back. Find the space behind the tree.","explain":"Behind the tree means at the back of the tree.","dskpTopic":"Recycled location and position; Year 6 language function 8 and earlier primary prepositions","learningStandard":"3.2.2 (preparatory language support)"},{"prompt":"The cat is between the rocks.","answer":"between","full":"The cat is between the rocks.","hint":"Between means in the middle of two things. Find the space between the two rocks.","explain":"Between the rocks means in the space between the two rocks.","dskpTopic":"Recycled location and position; Year 6 language function 8 and earlier primary prepositions","learningStandard":"3.2.2 (preparatory language support)"}],"subtitle":"Find a safe place for the cat"},{"id":"castle","title":"Giant Castle","topic":"Comparative & Superlative","type":"compare","color":"#e5b3f0","icon":"castle","x":89,"y":73,"guide":"Tap the building or chest that matches the instruction. Light up the castle!","taskLabel":"Castle light switched on","tasks":[{"prompt":"Choose the taller tower.","answer":"tall","objects":[{"id":"short","label":"Tower A","size":80},{"id":"tall","label":"Tower B","size":140}],"hint":"A taller tower is higher than the other tower. Compare the two towers.","explain":"Tower B is taller than Tower A. Taller compares two things.","dskpTopic":"Recycled comparative and superlative adjectives; Years 4–5 grammar in Year 6 Appendix 1","learningStandard":"3.2.2 (preparatory language support)","full":"Tower B is taller than Tower A."},{"prompt":"Choose the tallest tower.","answer":"tallest","objects":[{"id":"small","label":"Tower A","size":70},{"id":"medium","label":"Tower B","size":110},{"id":"tallest","label":"Tower C","size":158}],"hint":"The tallest tower is higher than all the other towers.","explain":"Tower C is the tallest of the three towers.","dskpTopic":"Recycled comparative and superlative adjectives; Years 4–5 grammar in Year 6 Appendix 1","learningStandard":"3.2.2 (preparatory language support)","full":"Tower C is the tallest of the three towers."},{"prompt":"Choose the smaller chest.","answer":"smaller","objects":[{"id":"bigger","label":"Chest A","size":128},{"id":"smaller","label":"Chest B","size":75}],"objectType":"chest","hint":"Look at the two chests. Choose the smaller one. It is less big.","explain":"Chest B is smaller than Chest A.","dskpTopic":"Recycled comparative and superlative adjectives; Years 4–5 grammar in Year 6 Appendix 1","learningStandard":"3.2.2 (preparatory language support)","full":"Chest B is smaller than Chest A."},{"prompt":"Choose the biggest chest.","answer":"biggest","objects":[{"id":"small","label":"Chest A","size":68},{"id":"biggest","label":"Chest B","size":140},{"id":"medium","label":"Chest C","size":100}],"objectType":"chest","hint":"Look at all three chests. Choose the largest one.","explain":"Chest B is the biggest of the three chests.","dskpTopic":"Recycled comparative and superlative adjectives; Years 4–5 grammar in Year 6 Appendix 1","learningStandard":"3.2.2 (preparatory language support)","full":"Chest B is the biggest of the three chests."},{"prompt":"Choose the shortest tower.","answer":"shortest","objects":[{"id":"tall","label":"Tower A","size":145},{"id":"shortest","label":"Tower B","size":70},{"id":"medium","label":"Tower C","size":108}],"hint":"Look at all three towers. Choose the lowest one.","explain":"Tower B is the shortest of the three towers.","dskpTopic":"Recycled comparative and superlative adjectives; Years 4–5 grammar in Year 6 Appendix 1","learningStandard":"3.2.2 (preparatory language support)","full":"Tower B is the shortest of the three towers."}],"subtitle":"Light up the castle"}],"rules":[["shop","Am / is / are","I am · He / she / it is · You / we / they are","Choose am, is or are to match the person or people in the sentence.","I am happy. She is a teacher."],["shop","Have / has","I / you / we / they have · He / she / it has","Have and has tell us what someone owns.","We have books. He has a bag."],["bridge","Pronouns","He = a boy · She = a girl · They = two or more people","Use his for something a boy owns. Use her for something a girl owns.","Ali is kind. He is kind. It is her book."],["train","Simple Present","I play · She plays · They play","Use it for routines. Many verbs take s or es after he, she or it.","She walks to school every day."],["boat","Present Continuous","am / is / are + verb-ing","Use it for actions happening now.","They are playing football."],["pickaxe","Simple Past","play → played · go → went · eat → ate","Use it for actions in the past. Many verbs take ed. Some verbs have a special past form.","Yesterday, I went to school."],["portal","Future","will + verb · am / is / are going to + verb","Use it for the future. After will or going to, use the base form of the verb.","She will visit grandma. We are going to play."],["cat","Prepositions","in · on · under · behind · between","Inside · on top · below · at the back · in the middle of two things.","The cat is under the table."],["castle","Comparisons","tall → taller → tallest","Use taller to compare two things. The tallest is higher than all the other things.","Tower B is taller. Tower C is the tallest."]],"curriculum":{"document":"KSSR (Semakan 2017) Standards-Based English Language Curriculum, Sekolah Kebangsaan, Year 6; Bahagian Pembangunan Kurikulum, Ministry of Education Malaysia, January 2022","title":"Year 6 supported primary grammar revision · 6B","url":"https://www.teacherfiera.com/wp-content/uploads/2020/04/2.-DSKP-KSSR-Semakan-2017-Bahasa-Inggeris-Tahun-6-SK_ISBN.pdf","grammarPages":"Printed syllabus pages 44–46; PDF pages 58–60. Earlier grammar: printed pages 52–53; PDF pages 66–67.","learningStandards":[{"code":"4.2.1","focus":"Foundational language for giving information about people."},{"code":"4.2.2","focus":"Foundational language for future plans and events."},{"code":"4.2.3","focus":"Foundational language for recounting events."},{"code":"4.2.5","focus":"Prerequisite pronouns for linking ideas."},{"code":"3.2.2","focus":"Prerequisite understanding of position and comparison instructions."}],"note":"Audited against the January 2022 KPM/BPK Year 6 SK DSKP. Retained as supported revision for a lower to lower-middle ability Year 6 class: sections 9–10 permit teachers to revisit Years 1–5 grammar, and Appendix 1 confirms the upper-primary foundations. This pack is prerequisite practice, not complete coverage of new Year 6 grammar or full learning standards. Original mission IDs, task order, prompts, answers, options and object definitions are unchanged so existing pupil progress remains valid. The five comparison tasks only gained missing full-sentence feedback. Game scores are not PBD performance levels.","topicAudit":[{"missionId":"market","status":"permitted revision","topic":"Recycled Years 1–5 be and have foundations; Year 6 syllabus sections 9–10 permit earlier grammar review"},{"missionId":"bridge","status":"permitted revision","topic":"Recycled subject pronouns and possessive adjectives; Year 6 syllabus sections 9–10 and Appendix 1"},{"missionId":"train","status":"permitted revision","topic":"Recycled present simple for routines; Year 4 routine-versus-current-action function in Year 6 Appendix 1"},{"missionId":"river","status":"permitted revision","topic":"Recycled present continuous; Year 4 routine-versus-current-action function in Year 6 Appendix 1"},{"missionId":"mine","status":"permitted revision","topic":"Recycled past simple, regular and irregular; Year 4 grammar in Year 6 Appendix 1"},{"missionId":"portal","status":"permitted revision","topic":"Year 6 future forms: will and going to; also recycled Year 4–5 grammar"},{"missionId":"rescue","status":"permitted revision","topic":"Recycled location and position; Year 6 language function 8 and earlier primary prepositions"},{"missionId":"castle","status":"permitted revision","topic":"Recycled comparative and superlative adjectives; Years 4–5 grammar in Year 6 Appendix 1"}],"kbatCount":0}},"y6-high":{"year":6,"levelLabel":"Challenge","missions":[{"id":"y6h-market","title":"Eco Market","subtitle":"Read the clues and help the shops","topic":"Passive voice · enough · comparisons","type":"rune","icon":"shop","color":"#ffbd64","x":18,"y":72,"guide":"Read every clue. Choose the message that is accurate and useful.","taskLabel":"Shop helped","reminder":"Remember: A passive sentence focuses on the thing receiving an action. Enough means the amount meets a need.","tasks":[{"prompt":"Every morning, workers wash the glass bottles. Choose the correct passive sentence about the bottles.","options":["The glass bottles are washed every morning.","The glass bottles is washed every morning.","The glass bottles are wash every morning."],"answer":"The glass bottles are washed every morning.","full":"The glass bottles are washed every morning.","hint":"Bottles is plural. Use are followed by the past participle washed.","explain":"Are washed focuses on the bottles that receive the action. Use are with a plural noun and washed after are.","scene":"friends","dskpTopic":"Year 6 passive voice","learningStandard":"3.2.2 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Workers make bags from old shirts and notebooks from old paper. A notice swaps the two materials. Which edit corrects both product-and-material relationships?","options":["The bags are made from old paper, and the notebooks are made from old shirts.","The bags are made from old shirts, and the notebooks are made from old paper.","The bags are made from old shirts, and the notebooks are made from old shirts."],"answer":"The bags are made from old shirts, and the notebooks are made from old paper.","full":"The bags are made from old shirts, and the notebooks are made from old paper.","hint":"Check each finished product separately. Bags use shirts; notebooks use paper. Both parts of the edit must be correct.","explain":"The edit restores both relationships: shirts become bags, and paper becomes notebooks. Are made from focuses on each product and names its material.","scene":"friends","dskpTopic":"Year 6 passive voice","learningStandard":"3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil separates two material-to-product relationships, detects the swapped references and selects an edit that restores both; every option uses the same correct passive form."},{"prompt":"A pie needs at least five apples. Box A has three, Box B has five and Box C has eight. Choose the smallest amount that is enough, without taking extra apples.","options":["Choose Box C because it has more apples than Box B.","Choose Box A because it has fewer apples than Box B.","Choose Box B because it has enough apples without any extra."],"answer":"Choose Box B because it has enough apples without any extra.","full":"Choose Box B because it has enough apples without any extra.","hint":"Check both conditions: at least five apples, and no extra apples.","explain":"A has too few apples. C has enough but includes three extra. B meets both conditions with exactly five apples.","scene":"apple","dskpTopic":"Year 6 comparisons with too and not enough; recycled comparisons","learningStandard":"2.1.3 / 3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"evaluate","kbatRationale":"The pupil evaluates three choices against a minimum quantity and a no-waste condition, then selects the reasoned recommendation; the grammar is correct in every option."},{"prompt":"Seven visitors each need one cup. Tray A has eight cups and Tray B has six. Which note explains why the shop should use Tray A?","options":["Tray B does not have enough cups, but Tray A does.","Both trays have enough cups for all seven visitors.","Tray A does not have enough cups, but Tray B does."],"answer":"Tray B does not have enough cups, but Tray A does.","full":"Tray B does not have enough cups, but Tray A does.","hint":"Compare each tray with seven visitors. Your note must describe both trays accurately.","explain":"Six cups are not enough for seven people, while eight cups are enough. The contrast supports using Tray A.","scene":"friends","dskpTopic":"Year 6 comparisons with not enough; recycled conjunctions","learningStandard":"2.1.3 / 3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil relates two quantities to a shared need and tests both parts of a contrasting statement; recalling the phrase enough cups does not identify the correct note."},{"prompt":"A paper bag becomes weak in the rain. A plastic bag stays strong when wet. It is raining now. Which packing note uses the evidence to protect the shopping?","options":["The shopping is packed in the paper bag because it stays strong when wet.","The shopping is packed in the plastic bag because it stays strong when wet.","The shopping is packed in the paper bag because there is no rain."],"answer":"The shopping is packed in the plastic bag because it stays strong when wet.","full":"The shopping is packed in the plastic bag because it stays strong when wet.","hint":"Match the bag material to the weather and check the reason after because.","explain":"The plastic bag stays strong in the given wet conditions. The passive note describes a choice supported by the material and weather clues.","scene":"friends","dskpTopic":"Year 6 passive voice; recycled conjunction because","learningStandard":"2.1.3 / 3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"evaluate","kbatRationale":"The pupil evaluates a practical choice using material properties and current weather, rejecting notes with an unsupported reason despite their grammatical form."}]},{"id":"y6h-bridge","title":"Message Bridge","subtitle":"Keep people and messages clear","topic":"Reported speech · question tags · reference pronouns","type":"bridge","icon":"bridge","color":"#80d4ea","x":38,"y":56,"guide":"Choose a message that keeps the facts, speakers and grammar correct.","taskLabel":"Message delivered","reminder":"Remember: Check who is speaking and who each pronoun means. A question tag checks a statement: can't ... , can ...?","tasks":[{"prompt":"Complete the question that checks this positive statement: You carry a map, ___?","options":["don't you","do you","isn't you"],"answer":"don't you","full":"You carry a map, don't you?","hint":"A positive present simple statement takes a negative tag with do.","explain":"Carry is a present simple verb. The positive statement You carry a map takes the negative question tag don't you.","scene":"friends","dskpTopic":"Year 6 question tags","learningStandard":"2.2.1 (supporting language practice)","kbat":false,"cognitiveLevel":"remember"},{"prompt":"Sara said, \"I am ready.\" Report her words later, changing am to its past form.","options":["Sara said she were ready.","Sara said she was ready.","Sara said she be ready."],"answer":"Sara said she was ready.","full":"Sara said she was ready.","hint":"I becomes she when you report Sara's words. The past form of am with she is was.","explain":"The report uses she for Sara and was as the past form of am. This task practises the requested past-form report.","scene":"girl","dskpTopic":"Year 6 reported speech","learningStandard":"2.3.1 / 4.2.3 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Ali told Sara, \"I have your map.\" Later, Sara tells Mina who had her map. Which is Sara's accurate report, using the past form had?","options":["Ali said Sara had his map.","Sara said she had Ali's map.","Ali said he had my map."],"answer":"Ali said he had my map.","full":"Ali said he had my map.","hint":"Ali spoke first, so he refers to Ali. Sara is now speaking, so her own map is my map.","explain":"Ali is the original speaker and map holder. In Sara's report, he refers to Ali and my refers to Sara, the map owner.","scene":"friends","dskpTopic":"Year 6 reported speech; recycled reference pronouns","learningStandard":"2.3.1 / 4.2.3 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil tracks the original speaker, current speaker and owner through a change of viewpoint; every option uses had, so tense recall alone is insufficient."},{"prompt":"Mina and her brother borrowed a boat together. Only her brother returned it. Mina's draft says, \"We borrowed the boat and we returned it.\" Which edit fixes who did the second action?","options":["We borrowed the boat, but he returned it.","He borrowed the boat, but we returned it.","We borrowed the boat, but she returned it."],"answer":"We borrowed the boat, but he returned it.","full":"We borrowed the boat, but he returned it.","hint":"We includes Mina and her brother. The second action was done by only one person: her brother.","explain":"We correctly describes the two borrowers. He identifies the brother as the only person who returned the boat, and it refers to the boat.","scene":"girl","dskpTopic":"Recycled reference pronouns and conjunctions","learningStandard":"4.2.5 / 4.3.3 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil compares a draft against two different sets of actors, locates the inaccurate reference and chooses an edit that preserves both events."},{"prompt":"The keeper says, \"Visitors can enter only before six.\" It is now six thirty. Which checking question follows the rule and uses the correct question tag?","options":["We can enter now, can't we?","We can't enter now, can we?","We can enter until seven, can't we?"],"answer":"We can't enter now, can we?","full":"We can't enter now, can we?","hint":"First decide whether entry is allowed at six thirty. Then use a positive tag after the negative statement.","explain":"Six thirty is after the entry deadline, so We can't enter now follows the rule. The negative statement takes the positive tag can we.","scene":"friends","dskpTopic":"Year 6 question tags; recycled can for permission","learningStandard":"2.1.2 / 2.2.1 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil applies a time restriction to the present situation, derives the permission statement and checks tag polarity; all three offered questions have grammatical tags."}]},{"id":"y6h-train","title":"Experience Train","subtitle":"Build questions about experience and time","topic":"Present perfect · ever · for · since · How long?","type":"train","icon":"train","color":"#a8d884","x":17,"y":34,"guide":"Put the carriages in order. Check have or has and the past participle.","taskLabel":"Train journey completed","reminder":"Remember: Use have or has with a past participle. For gives a length of time; since gives the starting point.","tasks":[{"prompt":"Ask whether your friend has visited Sabah at any time before now. Start with Have and end with Sabah?","words":["Have","you","ever","visited","Sabah?"],"answer":"Have you ever visited Sabah?","full":"Have you ever visited Sabah?","hint":"Put Have before you. Ever comes before the past participle visited.","explain":"Have you ever visited asks about an experience at any time up to now, without naming a finished past date.","scene":"friends","dskpTopic":"Year 6 present perfect with ever","learningStandard":"2.1.1 / 4.2.1 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Hana began living here in 2022 and still lives here. Build a sentence with since. Start with Hana and end with 2022.","words":["Hana","has","lived","here","since","2022."],"answer":"Hana has lived here since 2022.","full":"Hana has lived here since 2022.","hint":"Use has with Hana. Since introduces the starting year.","explain":"Has lived connects Hana's past starting point with the present. Since 2022 gives the starting point.","scene":"girl","dskpTopic":"Year 6 present perfect with since","learningStandard":"2.1.1 / 4.2.1 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Build a sentence saying that we began living here three years ago and still live here. Use for. Start with We and end with years.","words":["We","have","lived","here","for","three","years."],"answer":"We have lived here for three years.","full":"We have lived here for three years.","hint":"Use have with we. For introduces the length of time: three years.","explain":"Have lived describes a situation that continues now. For three years tells us its duration.","scene":"friends","dskpTopic":"Year 6 present perfect with for","learningStandard":"2.1.1 / 4.2.1 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Ask about the length of Amin's stay at the camp, which is still continuing. Start with How and end with camp?","words":["How","long","has","Amin","stayed","at","the","camp?"],"answer":"How long has Amin stayed at the camp?","full":"How long has Amin stayed at the camp?","hint":"Start with How long. Put has before Amin, then use the past participle stayed.","explain":"How long asks for a duration. Has Amin stayed uses present perfect for a stay that continues now.","scene":"boy","dskpTopic":"Year 6 present perfect with How long","learningStandard":"2.1.1 / 4.2.1 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Ask whether he has eaten dragon fruit at any time before now. Start with Has and end with fruit?","words":["Has","he","ever","eaten","dragon","fruit?"],"answer":"Has he ever eaten dragon fruit?","full":"Has he ever eaten dragon fruit?","hint":"Use has with he. The past participle of eat is eaten.","explain":"Has he ever eaten asks about an experience. Eaten is the past participle used after has.","scene":"apple","dskpTopic":"Year 6 present perfect with ever","learningStandard":"2.1.1 / 4.2.1 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"}]},{"id":"y6h-river","title":"River Timeline","subtitle":"Build a story about past actions","topic":"Past continuous with past simple · used to","type":"build","icon":"boat","color":"#69c8e8","x":56,"y":74,"guide":"Put the blocks in order. Show the action in progress and the event that happened.","taskLabel":"Story boat launched","reminder":"Remember: Was or were plus an ing verb shows a past action in progress. Used to describes a past habit or situation.","tasks":[{"prompt":"He began reading before the bell rang and was still reading at that moment. Start with He and end with rang.","words":["He","was","reading","when","the","bell","rang."],"answer":"He was reading when the bell rang.","full":"He was reading when the bell rang.","hint":"Use was reading for the action in progress. When introduces the shorter event.","explain":"Was reading is past continuous. The past simple rang names the event during that action.","scene":"boy","dskpTopic":"Year 6 past continuous with past simple","learningStandard":"2.3.1 / 4.2.3 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"They were on a walk when the rain began. Build the sentence. Start with They and end with rain.","words":["They","were","walking","when","it","started","to","rain."],"answer":"They were walking when it started to rain.","full":"They were walking when it started to rain.","hint":"Use were with they. Were walking is the action already in progress.","explain":"Were walking describes the continuing past action. Started describes when the rain began during the walk.","scene":"friends","dskpTopic":"Year 6 past continuous with past simple","learningStandard":"2.3.1 / 4.2.3 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"We played in this park regularly in the past, but we do not play here now. Start with We and end with here.","words":["We","used","to","play","here."],"answer":"We used to play here.","full":"We used to play here.","hint":"Use used to before the base verb play for the past habit.","explain":"Used to play describes the former routine. The prompt tells us this routine no longer continues.","scene":"friends","dskpTopic":"Year 6 used to","learningStandard":"2.3.1 / 4.2.3 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"She was a farmer before she became a teacher. Describe the former situation with used to. Start with She and end with farmer.","words":["She","used","to","be","a","farmer."],"answer":"She used to be a farmer.","full":"She used to be a farmer.","hint":"Used to is followed by a base verb. Here, use be.","explain":"Used to be describes her former situation. The prompt tells us her job has changed.","scene":"girl","dskpTopic":"Year 6 used to","learningStandard":"2.3.1 / 4.2.3 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"The cat escaped during Tom's sleep. Build the sentence with While. Start with While and end with escaped.","words":["While","Tom","was","sleeping,","the","cat","escaped."],"answer":"While Tom was sleeping, the cat escaped.","full":"While Tom was sleeping, the cat escaped.","hint":"While introduces the action in progress: Tom was sleeping. Put a comma before the main event.","explain":"Was sleeping is the background action. Escaped is the past simple event that happened during it.","scene":"friends","dskpTopic":"Year 6 past continuous with past simple","learningStandard":"2.3.1 / 4.2.3 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"}]},{"id":"y6h-mine","title":"Evidence Mine","subtitle":"Separate evidence from a guess","topic":"may · might · could · indefinite pronouns","type":"mine","icon":"pickaxe","color":"#acbcdf","x":68,"y":51,"guide":"Read the evidence. Choose a careful message that does not claim more than we know.","taskLabel":"Evidence gem found","reminder":"Remember: May, might and could can show a possibility. Nobody and nothing mean no person and no thing.","tasks":[{"prompt":"The basket is completely empty. Complete the sentence: There is ___ in the basket.","options":["nothing","someone","everything"],"answer":"nothing","full":"There is nothing in the basket.","hint":"An empty basket contains no things. Choose the pronoun that means no thing.","explain":"Nothing means no thing. It fits the information that the basket is empty.","scene":"friends","dskpTopic":"Year 6 indefinite pronouns","learningStandard":"3.2.2 (supporting language practice)","kbat":false,"cognitiveLevel":"remember"},{"prompt":"We hear a sound in the cave. It could be an animal or the wind. We have not looked inside. Which message uses the evidence carefully?","options":["An animal is definitely inside the cave.","There cannot be an animal inside the cave.","An animal may be inside the cave, but we are not sure."],"answer":"An animal may be inside the cave, but we are not sure.","full":"An animal may be inside the cave, but we are not sure.","hint":"A sound gives a possibility, but there are two possible causes. Avoid a claim of certainty.","explain":"May shows a possibility. The sound could come from an animal or the wind, so the evidence does not prove either cause.","scene":"friends","dskpTopic":"Year 6 modal verbs for speculation","learningStandard":"3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"evaluate","kbatRationale":"The pupil compares competing explanations with incomplete evidence and selects an appropriately uncertain claim; every option is a grammatical sentence."},{"prompt":"All three bags have been checked. The key is not in any bag. The table has not been checked. Which report separates a known fact from a possibility?","options":["The key isn't in any bag, and it isn't on the table.","We can't find the key in any bag, but it might be on the table.","The key is in a bag, but it might be on the table."],"answer":"We can't find the key in any bag, but it might be on the table.","full":"We can't find the key in any bag, but it might be on the table.","hint":"The bag search is complete. The table is still unknown, so use a possibility for the table.","explain":"The first part reports the completed search. Might be on the table is only a possibility because nobody has checked the table.","scene":"friends","dskpTopic":"Year 6 modal verbs for speculation and indefinite pronouns","learningStandard":"3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil distinguishes checked locations from an unchecked location, then tests a two-part statement for the correct degree of certainty in each part."},{"prompt":"After heavy rain, the hut floor is wet and its window is open. Which possible explanation is supported by both clues?","options":["The floor might be wet because sunshine came through the window.","The floor might be wet because the window was closed throughout the rain.","The floor might be wet because rain came through the open window."],"answer":"The floor might be wet because rain came through the open window.","full":"The floor might be wet because rain came through the open window.","hint":"Connect the wet weather to the open window. Use might because the clues support an explanation without proving it.","explain":"Rain and an open window together support this possible cause of the wet floor. Might keeps the explanation cautious.","scene":"friends","dskpTopic":"Year 6 modal verbs for speculation; recycled because and past simple","learningStandard":"3.2.2 / 2.1.3 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil connects weather, an opening and a wet floor to infer a plausible cause, while retaining uncertainty; all options contain the same correct modal form."},{"prompt":"Four children enter the mine. Only Nora and Amir carry lamps. Siti and Jun have none. No child has a map. Which edit fixes this draft: \"Everyone has a lamp, and someone has a map\"?","options":["Everyone has a lamp, but nobody has a map.","Some children have lamps, and someone has a map.","Some children have lamps, but nobody has a map."],"answer":"Some children have lamps, but nobody has a map.","full":"Some children have lamps, but nobody has a map.","hint":"Only two of the four children have lamps. Check the map statement separately.","explain":"Some accurately describes two of the four children. Nobody correctly reports that no child has a map. Both errors in the draft are fixed.","scene":"friends","dskpTopic":"Year 6 indefinite pronouns; recycled conjunctions and quantities","learningStandard":"3.2.2 / 4.3.3 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil checks two separate claims against a four-person set, detects both overgeneralisation and a false existence claim, and selects the only edit that fixes both."}]},{"id":"y6h-portal","title":"Decision Portal","subtitle":"Make a future plan from the clues","topic":"First conditional · future forms · timetables","type":"portal","icon":"portal","color":"#bea1fa","x":80,"y":27,"guide":"Choose the future message that fits every time, rule and plan clue.","taskLabel":"Decision portal opened","reminder":"Remember: In a first conditional, use present simple after if and will plus a base verb for the result. Timetables can use present simple.","tasks":[{"prompt":"Tomorrow's timetable says 9:00 am. Complete the timetable sentence: The train ___ at nine tomorrow morning.","options":["left","leaves","leaving"],"answer":"leaves","full":"The train leaves at nine tomorrow morning.","hint":"A fixed timetable can use present simple even when the event is tomorrow.","explain":"Leaves is present simple with the singular subject train. Present simple is used for this scheduled future event.","scene":"friends","dskpTopic":"Year 6 present simple for future events","learningStandard":"2.1.4 / 4.2.2 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"The race uses the field on dry days. On rainy days, it uses the hall only if the hall is open. Tomorrow the hall is closed. Which plan follows both rules if it rains?","options":["If it rains, we will hold the race another day.","If it rains, we will hold the race on the field.","If it rains, we will hold the race in the hall."],"answer":"If it rains, we will hold the race another day.","full":"If it rains, we will hold the race another day.","hint":"Rain rules out the field. The hall is allowed only when it is open, so check that restriction too.","explain":"Rain rules out the field, and the closed hall rules out the indoor choice. Holding the race another day follows both restrictions. If it rains uses present simple, followed by will hold for the result.","scene":"friends","dskpTopic":"Year 6 first conditional","learningStandard":"2.1.2 / 2.1.4 / 4.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil combines a weather rule with a separate hall-opening restriction, eliminates both immediate places and chooses a feasible future outcome; every option has a grammatical first conditional."},{"prompt":"The museum opens at ten and stays open all afternoon. Our bus reaches the stop at nine forty-five. The walk takes twenty minutes. Which entry plan is possible?","options":["We are going to enter the museum before ten.","We are going to enter the museum at nine forty-five.","We are going to enter the museum after ten."],"answer":"We are going to enter the museum after ten.","full":"We are going to enter the museum after ten.","hint":"Add the walk to the bus arrival time, then compare that time with the opening time.","explain":"Nine forty-five plus twenty minutes is ten oh five. The museum is open then, so the plan to enter after ten fits all the times.","scene":"friends","dskpTopic":"Year 6 future forms: going to; present simple for future events","learningStandard":"2.1.4 / 4.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"evaluate","kbatRationale":"The pupil calculates an arrival time and tests it against an opening constraint to choose a feasible plan; all options use the same correct going to structure."},{"prompt":"The club starts at four. From the bus stop, the walk takes twenty minutes. Bus A arrives at three fifty; Bus B arrives at three thirty. Which promise follows from the times?","options":["If we take Bus A, we will arrive before the club starts.","If we take Bus B, we will arrive before the club starts.","If we take Bus B, we will miss the start of the club."],"answer":"If we take Bus B, we will arrive before the club starts.","full":"If we take Bus B, we will arrive before the club starts.","hint":"Work out each arrival at the club, including the walk. Compare both with four o'clock.","explain":"Bus A gives an arrival of four ten, which is late. Bus B gives three fifty, so its conditional promise is supported by the times.","scene":"friends","dskpTopic":"Year 6 first conditional; present simple for future events","learningStandard":"2.1.4 / 4.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil combines travel stages for two alternatives and checks the predicted outcome of each conditional rather than selecting a verb form by recall."},{"prompt":"The gardener has bought seeds and made a firm plan to plant them tomorrow. The forecast says rain is possible, but not certain. Which note clearly states the plan and keeps the weather uncertain?","options":["He is going to plant seeds tomorrow, but it might rain.","He might plant seeds tomorrow, and it is certain to rain.","He is going to plant seeds tomorrow, and it cannot rain."],"answer":"He is going to plant seeds tomorrow, but it might rain.","full":"He is going to plant seeds tomorrow, but it might rain.","hint":"Use going to for the firm plan. Use a possibility word for the uncertain weather.","explain":"Is going to plant reports the planned action. Might rain respects the forecast's uncertainty and does not claim that rain is certain or impossible.","scene":"friends","dskpTopic":"Year 6 future forms and modal verbs for speculation","learningStandard":"2.1.4 / 4.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"evaluate","kbatRationale":"The pupil evaluates the certainty of two different pieces of information and selects a message that treats the planned action and uncertain forecast appropriately."}]},{"id":"y6h-rescue","title":"Rescue Rules","subtitle":"Choose advice with a clear reason","topic":"should · must · have to · do not have to","type":"rune","icon":"cat","color":"#ff9c95","x":42,"y":22,"guide":"Check the rules and the evidence. Choose accurate advice for the rescue team.","taskLabel":"Rescue team helped","reminder":"Remember: Should gives advice. Must and have to can show an obligation. Do not have to means something is not required.","tasks":[{"prompt":"Choose the grammatically correct advice for a child who needs help with a difficult task.","options":["You should to ask an adult for help.","You should ask an adult for help.","You should asks an adult for help."],"answer":"You should ask an adult for help.","full":"You should ask an adult for help.","hint":"Put a base verb directly after should, without to or s.","explain":"Should gives advice and is followed directly by the base verb ask.","scene":"friends","dskpTopic":"Year 6 modal verbs for advice","learningStandard":"2.1.3 (supporting language practice)","kbat":false,"cognitiveLevel":"remember"},{"prompt":"Wearing a helmet is a camp rule. Complete the sentence: Mina ___ to wear a helmet.","options":["have","having","has"],"answer":"has","full":"Mina has to wear a helmet.","hint":"Use has with one person, Mina. Has to shows that the rule requires it.","explain":"Has to expresses an obligation. The singular subject Mina takes has.","scene":"girl","dskpTopic":"Year 6 modal expressions for obligation: have to","learningStandard":"2.1.2 (supporting language practice)","kbat":false,"cognitiveLevel":"remember"},{"prompt":"The sign says: \"Helmets are required. Gloves are optional.\" Which message explains both rules accurately?","options":["You don't have to wear a helmet, but you must wear gloves.","You must wear a helmet, but you don't have to wear gloves.","You must wear a helmet, and you must wear gloves."],"answer":"You must wear a helmet, but you don't have to wear gloves.","full":"You must wear a helmet, but you don't have to wear gloves.","hint":"Required means an obligation. Optional means you may choose, so it is not required.","explain":"Must wear a helmet expresses the required action. Don't have to wear gloves means gloves are optional; it does not forbid them.","scene":"friends","dskpTopic":"Year 6 modal verbs for obligation","learningStandard":"2.1.2 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil distinguishes a compulsory item from an optional item and checks both clauses against the sign; every option uses grammatical obligation expressions."},{"prompt":"Ravi's water bottle is empty. Station A has drinking water and is five minutes away, but it is closed until tomorrow. Station B also has drinking water, is forty-five minutes away and is open now. Which advice fits his need and the opening times?","options":["You should fill your bottle at Station A because it is closer.","You should skip both stations because your bottle is full.","You should fill your bottle at Station B because it is open now."],"answer":"You should fill your bottle at Station B because it is open now.","full":"You should fill your bottle at Station B because it is open now.","hint":"A shorter journey helps only if the station can provide water now. Check whether each place is open.","explain":"Ravi needs water now. A is closer but closed; B is open. B is therefore the usable place in the stated choices, and the reason correctly explains that decision.","scene":"friends","dskpTopic":"Year 6 modal verbs for advice; recycled comparisons and because","learningStandard":"2.1.3 / 3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"evaluate","kbatRationale":"The pupil identifies the need, weighs distance against availability and rejects the tempting nearer but closed option; each option uses the same correct should structure."},{"prompt":"The rescue hall rule says everyone must keep quiet. The cat hides when it hears loud sounds. Amir suggests blowing a whistle; Lina suggests waiting calmly. Which message respects the rule and the cat's behaviour?","options":["We must keep the hall quiet, so we should blow the whistle.","We must keep the hall quiet, so we should wait calmly.","We don't have to keep the hall quiet, so we should shout."],"answer":"We must keep the hall quiet, so we should wait calmly.","full":"We must keep the hall quiet, so we should wait calmly.","hint":"Test each action against the quiet rule and the cat's reaction to loud sounds.","explain":"Waiting calmly keeps the hall quiet and avoids the loud sounds that make the cat hide. Must states the rule; should recommends the suitable action.","scene":"friends","dskpTopic":"Year 6 modal verbs for obligation and advice; recycled so","learningStandard":"2.1.2 / 2.1.3 (supporting language practice)","kbat":true,"cognitiveLevel":"evaluate","kbatRationale":"The pupil evaluates two proposed actions against both an external rule and behavioural evidence, choosing a recommendation with a consistent reason."}]},{"id":"y6h-castle","title":"Castle Evidence","subtitle":"Use more than one comparison clue","topic":"as ... as · enough · comparative and superlative forms","type":"compare","icon":"castle","color":"#e5b3f0","x":89,"y":73,"guide":"Look at the objects and read all the clues. Tap the one that fits.","taskLabel":"Castle light switched on","reminder":"Remember: As tall as means the same height. For a reasoning challenge, one matching clue is not enough: check every condition.","tasks":[{"prompt":"Tower A and Tower B have the same height. Choose the other tower that is as tall as Tower A.","objects":[{"id":"a","label":"Tower A","size":96},{"id":"b","label":"Tower B","size":96},{"id":"c","label":"Tower C","size":151}],"answer":"b","full":"Tower B is as tall as Tower A.","hint":"As tall as means equal in height. The instruction asks for a tower other than A.","explain":"Tower B and Tower A have the same height. Tower C is taller, so B matches as tall as A.","objectType":"tower","dskpTopic":"Year 6 comparisons with as, too and not enough; recycled comparative and superlative forms","learningStandard":"3.2.2 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Choose the tallest of these three towers.","objects":[{"id":"a","label":"Tower A","size":107},{"id":"b","label":"Tower B","size":76},{"id":"c","label":"Tower C","size":159}],"answer":"c","full":"Tower C is the tallest of the three towers.","hint":"The tallest tower is higher than every other tower in the group.","explain":"Tower C is higher than A and B, so the superlative tallest identifies C.","objectType":"tower","dskpTopic":"Year 6 comparisons with as, too and not enough; recycled comparative and superlative forms","learningStandard":"3.2.2 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Choose the chest that is smaller than Chest A.","objects":[{"id":"a","label":"Chest A","size":140},{"id":"b","label":"Chest B","size":88}],"answer":"b","full":"Chest B is smaller than Chest A.","hint":"Compare the two chests. Smaller means less big than the other one.","explain":"Chest B is less big than Chest A. Smaller is the comparative form of small.","objectType":"chest","dskpTopic":"Year 6 comparisons with as, too and not enough; recycled comparative and superlative forms","learningStandard":"3.2.2 (supporting language practice)","kbat":false,"cognitiveLevel":"understand"},{"prompt":"Chest A holds four gems, B holds eight and C holds twelve. The team has seven gems. Choose the smallest chest that is big enough for all seven.","objects":[{"id":"a","label":"Chest A · 4 gems","size":76},{"id":"b","label":"Chest B · 8 gems","size":111},{"id":"c","label":"Chest C · 12 gems","size":150}],"answer":"b","full":"Chest B is big enough for seven gems and smaller than Chest C.","hint":"First reject a chest that cannot hold seven gems. Then choose the smaller of the chests that can.","explain":"A is not big enough. B and C can hold seven gems, but B is smaller, so it meets both conditions.","objectType":"chest","dskpTopic":"Year 6 comparisons with as, too and not enough; recycled comparative and superlative forms","learningStandard":"3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"evaluate","kbatRationale":"The pupil eliminates an insufficient option, compares the remaining sufficient options and chooses the smallest feasible one; identifying the biggest or smallest alone fails."},{"prompt":"The key is in a tower taller than both A and C, but not as tall as D. Choose the only tower that fits all three comparisons.","objects":[{"id":"a","label":"Tower A","size":76},{"id":"b","label":"Tower B","size":143},{"id":"c","label":"Tower C","size":108},{"id":"d","label":"Tower D","size":164}],"answer":"b","full":"Tower B is taller than A and C, but it is not as tall as D.","hint":"Check taller than A, taller than C, and shorter than D separately. The answer must pass all three checks.","explain":"B is taller than both A and C and shorter than D. D fails the last condition, and A and C fail a taller-than condition.","objectType":"tower","dskpTopic":"Year 6 comparisons with as, too and not enough; recycled comparative and superlative forms","learningStandard":"3.2.2 (supporting language practice)","kbat":true,"cognitiveLevel":"analyse","kbatRationale":"The pupil combines three comparative relationships, rules out different distractors for different reasons and finds the one object satisfying the complete set of constraints."}]}],"rules":[["shop","Passive voice and enough","is / are + past participle · enough + noun · adjective + enough","A passive sentence focuses on the thing receiving the action. Enough means a need is met; not enough means it is not met.","The bags are made from old shirts. This tray has enough cups."],["bridge","Reports and checking questions","said + reported message · positive statement, negative tag?","In a past-form report, check pronouns and the changed verb. Question tags check understanding; match the tag to the statement.","Sara said she was ready. You carry a map, don't you? We can't enter, can we?"],["train","Experience and duration","have / has + past participle · ever · for / since · How long?","Ever asks about experience up to now. For gives a length of time. Since gives a starting point. How long asks for duration.","Have you ever visited Sabah? Hana has lived here since 2022."],["boat","Past actions and former habits","was / were + verb-ing + when + past event · used to + base verb","Past continuous describes a past action in progress. Past simple can name an event during it. Used to describes a past habit or situation.","He was reading when the bell rang. She used to be a farmer."],["pickaxe","Possibility and careful evidence","may / might / could + base verb · someone / nobody / nothing","A possibility is not a proven fact. Check which places or people are known, and which are still unknown. Nobody means no person; nothing means no thing.","The key might be on the table. Nobody has checked it yet."],["portal","Conditions and future plans","If + present simple, will + base verb · be going to · timetable present simple","Match a condition to its correct result. Going to can describe a plan. A fixed future timetable can use present simple.","If it rains, we will use the hall. The train leaves at nine tomorrow."],["cat","Rules and reasoned advice","should + base verb · must + base verb · have / has to · do not have to","Should gives advice. Must and have to can express an obligation. Do not have to means not required. A good reason must match the evidence.","You must wear a helmet, but you don't have to wear gloves."],["castle","Comparison decisions","as tall as · taller than · the tallest · big enough","As ... as compares equal qualities. A comparative relates things; a superlative gives an extreme in a group. Check every condition before choosing.","Chest B is big enough for seven gems and smaller than Chest C."]],"curriculum":{"document":"KSSR (Semakan 2017) Standards-Based English Language Curriculum, Sekolah Kebangsaan, Year 6; Bahagian Pembangunan Kurikulum, Ministry of Education Malaysia, January 2022","title":"Year 6 DSKP challenge grammar practice · 6S","url":"https://www.teacherfiera.com/wp-content/uploads/2020/04/2.-DSKP-KSSR-Semakan-2017-Bahasa-Inggeris-Tahun-6-SK_ISBN.pdf","grammarPages":"Printed syllabus pages 44–46; PDF pages 58–60. Earlier grammar: printed pages 52–53; PDF pages 66–67. HOTS: printed page 12; PDF page 26.","learningStandards":[{"code":"2.1.1 / 4.2.1","focus":"Language for sharing details about personal situations and experiences."},{"code":"2.1.2","focus":"Language for explaining what rules require."},{"code":"2.1.3","focus":"Advice supported by a relevant reason."},{"code":"2.1.4 / 4.2.2","focus":"Language for communicating planned or expected future actions."},{"code":"2.2.1","focus":"Checking an understood message during an exchange."},{"code":"2.3.1 / 4.2.3","focus":"Language for recounting past or imagined events."},{"code":"3.2.2","focus":"Understanding and relating details in written information."},{"code":"4.2.5","focus":"Reference pronouns and conjunctions that make connected ideas clear."},{"code":"4.3.3","focus":"Editing language so that a draft matches the intended meaning."}],"note":"Original Year 6 SK grammar activities for a higher-ability class. Topic boundaries follow the Year 6 grammar list and permitted recycling of earlier primary grammar. The challenge comes from connected clues, evidence, editing and decisions. These short tasks practise supporting language; they do not assess the full longer-text, interaction or two-paragraph learning standards, and game scores are not a PBD performance level.","kbatDefinition":"The KPM/BPK Year 6 DSKP, printed page 12, describes HOTS as using knowledge, skills and values for reasoning, reflection, problem solving and decisions, across applying, analysing, evaluating and creating. Here, a KBAT item requires a contextual inference or a decision against multiple facts or criteria; a direct form-recall, guided word-order or single comparison item is not counted. The task-level cognitiveLevel and kbatRationale record that distinction.","kbatCount":20,"kbatSource":{"url":"https://www.teacherfiera.com/wp-content/uploads/2020/04/2.-DSKP-KSSR-Semakan-2017-Bahasa-Inggeris-Tahun-6-SK_ISBN.pdf","page":"Printed page 12; PDF page 26","source":"KPM/BPK Year 6 SK DSKP, January 2022, Table 4"}}}};
const classByCode=code=>ROSTER.classes.find(c=>c.code===code);
const studentById=id=>ROSTER.students.find(s=>s.id===id);
const packForClass=code=>CONTENT_PACKS[classByCode(code)?.packId||'y6-supported'];
const missionsFor=id=>packForClass(studentById(id)?.classCode).missions;
let MISSIONS=CONTENT_PACKS['y6-supported'].missions,RULES=CONTENT_PACKS['y6-supported'].rules;
function usePack(code){const pack=packForClass(code);MISSIONS=pack.missions;RULES=pack.rules;}
